// =====================================================
// SPECIALとノーマルを区別する「特徴アンカー」
//
// 特にノーマル（わたぼう・ワルぼう・まおうのかげ等）と
// 性格領域が重なりやすいSPECIALだけ、もう一段の特徴を要求する。
// 「遊び心が高いだけでオルゴ」のような吸い込みを防ぐ。
// =====================================================

const SPECIAL_DISTINCTIVE_RULES = {

  orgo: {
    description:
      "自在さ・策略に加えて、はっきりした野心が必要",
    all: [
      { type: "flag", key: "TRICK", min: 1.5 },
      { type: "axis", key: "AMBI", min: 65 }
    ],
    any: [
      { type: "axis", key: "AMBI", min: 75 },
      { type: "flag", key: "AMBITION", min: 2 }
    ]
  },

  god: {
    description:
      "好奇心と遊び心に加えて、俯瞰できる冷静さと知略が必要",
    all: [
      { type: "axis", key: "CURI", min: 76 },
      { type: "axis", key: "PLAY", min: 70 },
      { type: "axis", key: "CALM", min: 72 },
      { type: "axis", key: "INT", min: 68 }
    ],
    any: [
      { type: "axis", key: "PATI", min: 62 },
      { type: "flag", key: "COMPOSURE", min: 1 }
    ]
  },

  zoma: {
    description:
      "冷静・知略・孤高だけでなく、支配や大きな目的への志向が必要",
    any: [
      { type: "axis", key: "AMBI", min: 62 },
      { type: "flag", key: "CONTROL", min: 1 },
      { type: "flag", key: "POWER", min: 2 }
    ]
  }

};


function getSpecialDistinctiveValue(
  rule,
  userProfile
) {

  if (rule.type === "axis") {
    return userProfile[rule.key] ?? 50;
  }

  return diagnosisState
    .flags[rule.key] ?? 0;
}


function evaluateSpecialDistinctiveCondition(
  specialId,
  userProfile
) {

  const rules =
    SPECIAL_DISTINCTIVE_RULES[
      specialId
    ];

  if (!rules) {
    return {
      passed: true,
      description:
        "追加アンカー不要"
    };
  }

  const allPassed =
    (rules.all ?? [])
      .every(
        rule =>
          getSpecialDistinctiveValue(
            rule,
            userProfile
          ) >= rule.min
      );

  const anyRules =
    rules.any ?? [];

  const anyPassed =
    anyRules.length === 0 ||
    anyRules.some(
      rule =>
        getSpecialDistinctiveValue(
          rule,
          userProfile
        ) >= rule.min
    );

  return {
    passed:
      allPassed && anyPassed,
    description:
      rules.description
  };
}


// =====================================================
// SPECIALプロフィール検証
// =====================================================

function validateSpecialProfiles() {

  const errors = [];

  if (
    Object.keys(SPECIAL_PROFILES).length !==
    SPECIAL_BASE_TYPES.length
  ) {
    errors.push(
      "SPECIALタイプ数とプロフィール数が一致していません。"
    );
  }

  for (const special of SPECIAL_BASE_TYPES) {

    const profile =
      SPECIAL_PROFILES[special.id];

    if (!profile) {
      errors.push(
        `${special.name} のSPECIALプロフィールがありません。`
      );
      continue;
    }

    for (const axis of AXES) {

      const value = profile[axis];

      if (
        typeof value !== "number" ||
        value < 0 ||
        value > 100
      ) {
        errors.push(
          `${special.name}: ${axis} が不正です。`
        );
      }

    }

  }

  return errors;
}


// =====================================================
// SPECIAL：軸の重要度
// =====================================================

function getSpecialAxisWeight(
  specialId,
  axis
) {

  const importance =
    SPECIAL_AXIS_IMPORTANCE[
      specialId
    ];

  if (!importance) {
    return 0.7;
  }

  if (
    importance.core.includes(axis)
  ) {
    return 2.0;
  }

  if (
    importance.secondary.includes(axis)
  ) {
    return 1.3;
  }

  return 0.7;
}


// =====================================================
// SPECIAL：プロフィール一致度
// =====================================================

function calculateSpecialProfileSimilarity(
  userProfile,
  specialId
) {

  const specialProfile =
    SPECIAL_PROFILES[specialId];

  if (!specialProfile) {
    return 0;
  }

  let weightedDistance = 0;
  let totalWeight = 0;

  for (const axis of AXES) {

    const userValue =
      Number(userProfile[axis]);

    const targetValue =
      Number(specialProfile[axis]);

    if (
      !Number.isFinite(userValue) ||
      !Number.isFinite(targetValue)
    ) {
      continue;
    }

    const weight =
      getSpecialAxisWeight(
        specialId,
        axis
      );

    weightedDistance +=
      Math.abs(
        userValue - targetValue
      ) * weight;

    totalWeight += weight;
  }

  if (totalWeight <= 0) {
    return 0;
  }

  return Math.max(
    0,
    Math.min(
      100,
      100 -
      weightedDistance / totalWeight
    )
  );
}


// =====================================================
// SPECIAL：キー一致度
// =====================================================

function calculateSpecialKeyMatch(
  specialId
) {

  const rule =
    SPECIAL_KEY_RULES[specialId];

  if (!rule) {
    return {
      score: 0,
      hits: 0,
      minHits: 1
    };
  }

  let weightedRatio = 0;
  let totalWeight = 0;
  let hits = 0;

  for (
    const [key, config]
    of Object.entries(rule.keys)
  ) {

    const actual =
      Math.max(
        0,
        diagnosisState.flags[key] ?? 0
      );

    const target =
      Math.max(
        0.1,
        config.target ?? 1
      );

    const weight =
      Math.max(
        0.1,
        config.weight ?? 1
      );

    const ratio =
      Math.min(
        1,
        actual / target
      );

    weightedRatio +=
      ratio * weight;

    totalWeight += weight;

    if (
      actual >= target * 0.75
    ) {
      hits++;
    }

  }

  const score =
    totalWeight > 0
      ? 100 *
        weightedRatio /
        totalWeight
      : 0;

  return {
    score,
    hits,
    minHits: rule.minHits ?? 1
  };
}


// =====================================================
// SPECIAL：重要軸がどれだけ強く一致しているか
// =====================================================

function calculateSpecialCoreAlignment(
  userProfile,
  specialId
) {

  const importance =
    SPECIAL_AXIS_IMPORTANCE[
      specialId
    ];

  const targetProfile =
    SPECIAL_PROFILES[specialId];

  if (
    !importance ||
    !targetProfile
  ) {
    return {
      aligned: 0,
      total: 0
    };
  }

  let aligned = 0;

  for (
    const axis
    of importance.core
  ) {

    const user =
      userProfile[axis] ?? 50;

    const target =
      targetProfile[axis] ?? 50;

    if (
      target >= 65 &&
      user >= 65
    ) {
      aligned++;
    } else if (
      target <= 35 &&
      user <= 35
    ) {
      aligned++;
    } else if (
      target > 35 &&
      target < 65 &&
      Math.abs(user - target) <= 15
    ) {
      aligned++;
    }

  }

  return {
    aligned,
    total: importance.core.length
  };
}


// =====================================================
// SPECIAL：重要軸の回答一貫性
// =====================================================

function calculateSpecialConsistency(
  specialId
) {

  const importance =
    SPECIAL_AXIS_IMPORTANCE[
      specialId
    ];

  const targetProfile =
    SPECIAL_PROFILES[specialId];

  if (
    !importance ||
    !targetProfile
  ) {
    return 50;
  }

  let sum = 0;
  let count = 0;

  for (
    const axis
    of importance.core
  ) {

    const evidence =
      diagnosisState
        .axisEvidence[axis] ?? 0;

    if (evidence <= 0) {
      continue;
    }

    const rawDirection =
      Math.max(
        -1,
        Math.min(
          1,
          (diagnosisState
            .axisScores[axis] ?? 0) /
          evidence
        )
      );

    const target =
      targetProfile[axis] ?? 50;

    let targetDirection = 0;

    if (target >= 65) {
      targetDirection = 1;
    } else if (target <= 35) {
      targetDirection = -1;
    }

    let axisConsistency;

    if (targetDirection === 0) {
      axisConsistency =
        100 *
        (1 - Math.abs(rawDirection));
    } else {
      axisConsistency =
        50 +
        50 *
        rawDirection *
        targetDirection;
    }

    sum += Math.max(
      0,
      Math.min(
        100,
        axisConsistency
      )
    );

    count++;
  }

  return count > 0
    ? sum / count
    : 50;
}


// =====================================================
// SPECIAL：性格の極端さ
// =====================================================

function calculateSpecialExtremity(
  userProfile,
  specialId
) {

  const importance =
    SPECIAL_AXIS_IMPORTANCE[
      specialId
    ];

  if (!importance) {
    return 0;
  }

  const axes = [
    ...importance.core,
    ...importance.secondary.slice(0, 2)
  ];

  const values =
    axes.map(axis =>
      Math.min(
        100,
        Math.abs(
          (userProfile[axis] ?? 50) -
          50
        ) * 2
      )
    );

  return values.length > 0
    ? values.reduce(
        (sum, value) => sum + value,
        0
      ) / values.length
    : 0;
}


// =====================================================
// SPECIAL候補は出現率補正を行わず、回答との一致だけで順位付け
// =====================================================

// =====================================================
// SPECIAL：15タイプ順位
// =====================================================

function rankSpecialCandidates(
  userProfile
) {

  return SPECIAL_BASE_TYPES
    .map(special => {

      const profileScore =
        calculateSpecialProfileSimilarity(
          userProfile,
          special.id
        );

      const keyMatch =
        calculateSpecialKeyMatch(
          special.id
        );

      const alignment =
        calculateSpecialCoreAlignment(
          userProfile,
          special.id
        );

      const consistency =
        calculateSpecialConsistency(
          special.id
        );

      const extremity =
        calculateSpecialExtremity(
          userProfile,
          special.id
        );

      const distinctive =
        evaluateSpecialDistinctiveCondition(
          special.id,
          userProfile
        );

      // 深掘り質問前の入口判定。
      // SPECIAL直接点は次の段階で加える。
      const gateScore =
        profileScore * 0.65 +
        keyMatch.score * 0.20 +
        consistency * 0.10 +
        extremity * 0.05;

      return {
        id: special.id,
        name: special.name,
        profileScore,
        keyScore: keyMatch.score,
        keyHits: keyMatch.hits,
        minKeyHits: keyMatch.minHits,
        alignedCoreAxes: alignment.aligned,
        totalCoreAxes: alignment.total,
        consistency,
        extremity,
        distinctive,
        gateScore
      };

    })
    .sort(
      (a, b) =>
        b.gateScore -
        a.gateScore
    );
}


// =====================================================
// SPECIALゲート
// =====================================================

function evaluateSpecialGate() {

  const userProfile =
    buildCurrentUserProfile();

  const ranking =
    rankSpecialCandidates(
      userProfile
    );

  const first = ranking[0];
  const second = ranking[1];

  if (!first) {
    return {
      passed: false,
      reason:
        "SPECIAL候補を計算できませんでした。",
      ranking
    };
  }

  const gap =
    second
      ? first.gateScore -
        second.gateScore
      : first.gateScore;

  const reasons = [];

  const bestNormalProfile =
    rankNormalMonsters(
      userProfile
    )[0];

  const normalProfileGap =
    bestNormalProfile
      ? first.profileScore -
        bestNormalProfile.similarity
      : 0;

  // SPECIALのプロフィールがノーマル候補より明確に弱い場合は、
  // 「珍しい結果だから」という理由だけでSPECIALへ入れない。
  if (
    bestNormalProfile &&
    normalProfileGap < -2.5
  ) {
    reasons.push(
      "ノーマル候補よりプロフィール一致が弱い"
    );
  }

  if (
    !first.distinctive?.passed
  ) {
    reasons.push(
      `SPECIAL固有の特徴が不足（${first.distinctive.description}）`
    );
  }

  if (
    first.profileScore < 80
  ) {
    reasons.push(
      "プロフィール一致が不足"
    );
  }

  if (
    first.gateScore < 89.65
  ) {
    reasons.push(
      "総合SPECIAL適性が不足"
    );
  }

  if (
    first.keyHits <
    first.minKeyHits
  ) {
    reasons.push(
      "固有キーが不足"
    );
  }

  if (
    first.alignedCoreAxes < 2
  ) {
    reasons.push(
      "主要性格軸の一致が不足"
    );
  }

  if (
    first.consistency < 55
  ) {
    reasons.push(
      "回答傾向の一貫性が不足"
    );
  }

  const passed =
    reasons.length === 0;

  return {
    passed,
    reason:
      passed
        ? `SPECIAL深掘り条件を通過（${first.name}候補）`
        : reasons.join("・"),
    candidate: first,
    second,
    gap,
    normalProfileGap,
    bestNormalProfile,
    ranking
  };
}



