// =====================================================
// SPECIAL深掘り：回答数
// =====================================================

function getSpecialDeepAnswerCount() {

  return diagnosisState
    .answeredIds
    .filter(
      id => id.startsWith("S")
    )
    .length;
}


// =====================================================
// SPECIAL深掘り：直接点を0～100へ変換
// =====================================================

function calculateSpecialDirectScore(
  specialId
) {

  const raw =
    diagnosisState
      .specialDirectScores[
        specialId
      ] ?? 0;

  return Math.min(
    100,
    raw / 10 * 100
  );
}


// =====================================================
// SPECIAL深掘り：最新ランキング
// 55% profile / 25% keys / 10% direct /
// 5% extremity / 5% consistency
// =====================================================

function rankSpecialCandidatesForDeep(
  userProfile
) {

  return rankSpecialCandidates(
    userProfile
  )
    .map(candidate => {

      const directRaw =
        diagnosisState
          .specialDirectScores[
            candidate.id
          ] ?? 0;

      const directScore =
        calculateSpecialDirectScore(
          candidate.id
        );

      const deepScore =
        candidate.profileScore * 0.55 +
        candidate.keyScore * 0.25 +
        directScore * 0.10 +
        candidate.extremity * 0.05 +
        candidate.consistency * 0.05;

      return {
        ...candidate,
        directRaw,
        directScore,
        deepScore
      };

    })
    .sort(
      (a, b) =>
        b.deepScore -
        a.deepScore
    );
}


// =====================================================
// SPECIAL深掘り：次の質問を選択
// =====================================================

function selectNextSpecialDeepQuestion() {

  const profile =
    buildCurrentUserProfile();

  const ranking =
    rankSpecialCandidatesForDeep(
      profile
    );

  const topCandidates =
    ranking.slice(0, 6);

  const first =
    topCandidates[0];

  const second =
    topCandidates[1];

  const recentFormats =
    diagnosisState.recentFormats;

  const lastFormat =
    recentFormats.at(-1);

  const secondLastFormat =
    recentFormats.at(-2);

  let bestQuestion = null;
  let bestScore = -Infinity;

  for (
    const question
    of SPECIAL_DEEP_QUESTIONS
  ) {

    if (
      diagnosisState
        .answeredIds
        .includes(question.id)
    ) {
      continue;
    }

    let score = 0;

    topCandidates.forEach(
      (candidate, index) => {

        if (
          question.targets.includes(
            candidate.id
          )
        ) {
          score += 8 - index;
        }

      }
    );

    // 1位と2位の両方を含む質問は
    // 接戦時の識別に向いている
    if (
      first &&
      second &&
      question.targets.includes(
        first.id
      ) &&
      question.targets.includes(
        second.id
      )
    ) {
      score += 5;
    }

    if (
      question.theme &&
      diagnosisState
        .recentThemes
        .includes(question.theme)
    ) {
      score -= 5;
    }

    if (
      lastFormat &&
      question.format ===
      lastFormat
    ) {
      score -= 2;
    }

    if (
      lastFormat &&
      secondLastFormat &&
      lastFormat ===
      secondLastFormat &&
      question.format ===
      lastFormat
    ) {
      score -= 7;
    }

    if (
      question.format ===
      "EXTREME" &&
      recentFormats.includes(
        "EXTREME"
      )
    ) {
      score -= 6;
    }

    if (score > bestScore) {
      bestScore = score;
      bestQuestion = question;
    }

  }

  return bestQuestion;
}


// =====================================================
// SPECIAL深掘り：続行／終了判定
// 6～10問の可変式
// =====================================================

function evaluateSpecialDeepProgress() {

  const count =
    getSpecialDeepAnswerCount();

  const profile =
    buildCurrentUserProfile();

  const ranking =
    rankSpecialCandidatesForDeep(
      profile
    );

  const first = ranking[0];
  const second = ranking[1];

  const gap =
    first && second
      ? first.deepScore -
        second.deepScore
      : 0;

  if (count < 6) {
    return {
      shouldStop: false,
      reason:
        `SPECIAL深掘りを続行（${count}/6問）`,
      ranking,
      gap
    };
  }

  if (
    first &&
    count >= 6 &&
    first.deepScore >= 82 &&
    first.directRaw >= 5 &&
    gap >= 5
  ) {
    return {
      shouldStop: true,
      reason:
        `SPECIAL候補が十分に絞れました（差 ${gap.toFixed(1)}）`,
      ranking,
      gap
    };
  }

  if (
    first &&
    count >= 8 &&
    first.deepScore >= 78 &&
    first.directRaw >= 4 &&
    gap >= 3
  ) {
    return {
      shouldStop: true,
      reason:
        `追加確認後に候補が絞れました（差 ${gap.toFixed(1)}）`,
      ranking,
      gap
    };
  }

  if (count >= 10) {
    return {
      shouldStop: true,
      reason:
        "SPECIAL深掘りを最大10問まで確認したため終了",
      ranking,
      gap
    };
  }

  return {
    shouldStop: false,
    reason:
      `SPECIAL候補がまだ近いため続行（差 ${gap.toFixed(1)}）`,
    ranking,
    gap
  };
}


// =====================================================
// SPECIAL深掘り：最終継続判定
// ※ここで失敗した場合はノーマル結果へ戻る
// =====================================================

function evaluateSpecialDeepResult() {

  const profile =
    buildCurrentUserProfile();

  const ranking =
    rankSpecialCandidatesForDeep(
      profile
    );

  const first = ranking[0];
  const second = ranking[1];

  if (!first) {
    return {
      passed: false,
      reason:
        "SPECIAL候補を計算できませんでした。",
      ranking
    };
  }

  const reasons = [];

  const bestNormalProfile =
    rankNormalMonsters(
      profile
    )[0];

  const normalProfileGap =
    bestNormalProfile
      ? first.profileScore -
        bestNormalProfile.similarity
      : 0;

  if (
    bestNormalProfile &&
    normalProfileGap < -1.0
  ) {
    reasons.push(
      "深掘り後もノーマル候補との差が不足"
    );
  }

  if (
    !first.distinctive?.passed
  ) {
    reasons.push(
      `SPECIAL固有の特徴が不足（${first.distinctive.description}）`
    );
  }

  if (
    first.profileScore < 76
  ) {
    reasons.push(
      "プロフィール一致が不足"
    );
  }

  if (
    first.deepScore < 88.5
  ) {
    reasons.push(
      "深掘り後のSPECIAL適性が不足"
    );
  }

  if (
    first.keyHits <
    first.minKeyHits
  ) {
    reasons.push(
      "固有キーが不足"
    );
  }

  if (
    first.alignedCoreAxes < 2
  ) {
    reasons.push(
      "主要性格軸の一致が不足"
    );
  }

  if (
    first.consistency < 50
  ) {
    reasons.push(
      "回答傾向の一貫性が不足"
    );
  }

  if (
    first.directRaw < 7
  ) {
    reasons.push(
      "SPECIAL専用回答の裏付けが不足"
    );
  }

  const gap =
    second
      ? first.deepScore -
        second.deepScore
      : first.deepScore;

  if (
    gap < 1.0 &&
    first.deepScore < 92
  ) {
    reasons.push(
      "SPECIAL候補同士の差が不足"
    );
  }

  const passed =
    reasons.length === 0;

  return {
    passed,
    reason:
      passed
        ? `SPECIAL深掘りを通過（${first.name}候補）`
        : reasons.join("・"),
    candidate: first,
    second,
    gap,
    normalProfileGap,
    bestNormalProfile,
    ranking
  };
}


// =====================================================
// SPECIAL深掘り：開始
// =====================================================

function startSpecialDeepStep() {

  diagnosisState.route =
    "SPECIAL_DEEP";

  setDiagnosisProgress(
    77,
    "SPECIAL適性を深掘り中"
  );

  // ノーマル分岐の直前履歴を
  // SPECIAL質問選びへ引きずらない
  diagnosisState.recentThemes = [];
  diagnosisState.recentFormats = [];

  const nextQuestion =
    selectNextSpecialDeepQuestion();

  if (nextQuestion) {
    renderQuestion(
      nextQuestion
    );
    return;
  }

  showSpecialDeepSummary();
}


// =====================================================
// SPECIAL深掘り：終了画面
// =====================================================

function showSpecialDeepSummary() {

  setDiagnosisProgress(
    92,
    "SPECIAL深掘りが完了しました"
  );

  const progress =
    evaluateSpecialDeepProgress();

  const result =
    evaluateSpecialDeepResult();

  diagnosisState.specialDeepResult =
    result;

  diagnosisState.specialCandidateId =
    result.candidate?.id ??
    diagnosisState.specialCandidateId;

  const questionText =
    document.getElementById(
      "questionText"
    );

  const answerButtons =
    document.getElementById(
      "answerButtons"
    );

  const answerStatus =
    document.getElementById(
      "answerStatus"
    );

  const answeredIds =
    diagnosisState
      .answeredIds
      .filter(
        id => id.startsWith("S")
      );

  questionText.textContent =
    "SPECIAL深掘り完了";

  answerButtons.innerHTML = "";

  const resultBox =
    document.createElement(
      "div"
    );

  resultBox.className =
    "analysis-output";

  const lines = [];

  lines.push(
    `回答したSPECIAL質問：${answeredIds.join(" → ")}`
  );

  lines.push(
    `SPECIAL質問数：${answeredIds.length}問`
  );

  lines.push(
    `終了理由：${progress.reason}`
  );

  lines.push("");
  lines.push(
    "【SPECIAL深掘り判定】"
  );

  if (result.passed) {

    lines.push(
      `判定：PASS（${result.candidate.name}候補）`
    );

    lines.push(
      `深掘り適性：${result.candidate.deepScore.toFixed(1)}`
    );

    lines.push(
      `プロフィール一致：${result.candidate.profileScore.toFixed(1)}`
    );

    lines.push(
      `固有キー一致：${result.candidate.keyScore.toFixed(1)}`
    );

    lines.push(
      `専用回答点：${result.candidate.directRaw.toFixed(1)}`
    );

    lines.push(
      `2位との差：${result.gap.toFixed(1)}`
    );

  } else {

    lines.push(
      "判定：ノーマル結果へ戻る"
    );

    if (result.candidate) {
      lines.push(
        `最有力SPECIAL候補：${result.candidate.name}`
      );
      lines.push(
        `深掘り適性：${result.candidate.deepScore.toFixed(1)}`
      );
    }

    lines.push(
      `理由：${result.reason}`
    );

  }

  resultBox.textContent =
    lines.join("\n");

  answerButtons.appendChild(
    resultBox
  );

  const awakeningTargets = [
    "ryuou",
    "nergel",
    "elgios",
    "orgo",
    "deathmore",
    "mildrath",
    "rhapthorne"
  ];

  if (
    result.passed &&
    awakeningTargets.includes(
      result.candidate.id
    )
  ) {

    const awakeningButton =
      document.createElement(
        "button"
      );

    awakeningButton.className =
      "answer-button";

    awakeningButton.textContent =
      "覚醒・変身判定へ進む";

    awakeningButton.addEventListener(
      "click",
      startAwakeningStep
    );

    answerButtons.appendChild(
      awakeningButton
    );

  } else {

    appendFinalResultButton(
      answerButtons
    );

  }

  if (
    result.passed &&
    awakeningTargets.includes(
      result.candidate.id
    )
  ) {
    answerStatus.textContent =
      "SPECIAL候補を確認しました。次は覚醒・変身形態の判定へ進みます。";
  } else if (result.passed) {
    answerStatus.textContent =
      "SPECIAL候補を確認しました。最終結果を表示できます。";
  } else {
    answerStatus.textContent =
      "SPECIAL条件が深掘りで確認できなかったため、ノーマル結果を表示します。";
  }
}


