// =====================================================
// 覚醒・変身：回答点を加算
// =====================================================

function applyAwakeningEffects(
  effects = {}
) {

  for (
    const [side, value]
    of Object.entries(effects)
  ) {

    if (
      side !== "base" &&
      side !== "awakened"
    ) {
      continue;
    }

    diagnosisState
      .awakeningScores[side] +=
      value;
  }
}


// =====================================================
// 覚醒・変身：回答数
// =====================================================

function getAwakeningAnswerCount() {

  return diagnosisState
    .answeredIds
    .filter(
      id => id.startsWith("A_")
    )
    .length;
}


// =====================================================
// 2つの値を0～100の比率へ変換
// awakened側の割合を返す
// =====================================================

function calculatePairShare(
  baseValue,
  awakenedValue
) {

  const total =
    Math.max(0, baseValue) +
    Math.max(0, awakenedValue);

  if (total <= 0) {
    return 50;
  }

  return Math.max(
    0,
    Math.min(
      100,
      awakenedValue /
      total *
      100
    )
  );
}


// =====================================================
// 覚醒・変身：キー支持率
// =====================================================

function calculateAwakeningKeySupport(
  rule
) {

  const averageStrength =
    keys => {

      if (!keys.length) {
        return 0;
      }

      const total =
        keys.reduce(
          (sum, key) => {

            const raw =
              Math.max(
                0,
                diagnosisState
                  .flags[key] ?? 0
              );

            return (
              sum +
              Math.min(
                1,
                raw / 3
              )
            );

          },
          0
        );

      return total /
        keys.length;
    };

  const base =
    averageStrength(
      rule.baseKeys
    );

  const awakened =
    averageStrength(
      rule.awakenedKeys
    );

  return calculatePairShare(
    base,
    awakened
  );
}


// =====================================================
// 覚醒・変身：性格軸支持率
// =====================================================

function calculateAwakeningAxisSupport(
  rule
) {

  const profile =
    buildCurrentUserProfile();

  const average =
    axes => {

      if (!axes.length) {
        return 50;
      }

      return (
        axes.reduce(
          (sum, axis) =>
            sum +
            (profile[axis] ?? 50),
          0
        ) /
        axes.length
      );
    };

  return calculatePairShare(
    average(rule.baseAxes),
    average(rule.awakenedAxes)
  );
}


// =====================================================
// 覚醒・変身：専用回答支持率
// =====================================================

function calculateAwakeningDedicatedSupport() {

  return calculatePairShare(
    diagnosisState
      .awakeningScores.base,
    diagnosisState
      .awakeningScores.awakened
  );
}


// =====================================================
// 覚醒・変身：専用回答の一貫性
// =====================================================

function calculateAwakeningConsistency() {

  const base =
    diagnosisState
      .awakeningScores.base;

  const awakened =
    diagnosisState
      .awakeningScores.awakened;

  const total =
    base + awakened;

  if (total <= 0) {
    return 50;
  }

  return (
    Math.max(
      base,
      awakened
    ) /
    total *
    100
  );
}


// =====================================================
// 覚醒・変身：総合スコア
// 50% 専用回答
// 25% 既存キー
// 20% 性格軸
// 5%  回答一貫性
// =====================================================

function calculateAwakeningScore(
  candidateId =
    diagnosisState
      .awakeningCandidateId
) {

  const rule =
    SPECIAL_AWAKENING_RULES[
      candidateId
    ];

  if (!rule) {
    return null;
  }

  const dedicated =
    calculateAwakeningDedicatedSupport();

  const keySupport =
    calculateAwakeningKeySupport(
      rule
    );

  const axisSupport =
    calculateAwakeningAxisSupport(
      rule
    );

  const consistency =
    calculateAwakeningConsistency();

  const consistencySupport =
    dedicated >= 50
      ? consistency
      : 100 - consistency;

  const awakenedScore =
    dedicated * 0.50 +
    keySupport * 0.25 +
    axisSupport * 0.20 +
    consistencySupport * 0.05;

  return {
    rule,
    dedicated,
    keySupport,
    axisSupport,
    consistency,
    awakenedScore:
      Math.max(
        0,
        Math.min(
          100,
          awakenedScore
        )
      ),
    baseScore:
      Math.max(
        0,
        Math.min(
          100,
          100 - awakenedScore
        )
      )
  };
}


// =====================================================
// 覚醒・変身：次の質問
// =====================================================

function selectNextAwakeningQuestion() {

  const candidateId =
    diagnosisState
      .awakeningCandidateId;

  const questions =
    AWAKENING_QUESTIONS.filter(
      question =>
        question.target ===
        candidateId
    );

  const regular =
    questions.filter(
      question =>
        !question.tieBreaker
    );

  const tieBreaker =
    questions.find(
      question =>
        question.tieBreaker
    );

  const nextRegular =
    regular.find(
      question =>
        !diagnosisState
          .answeredIds
          .includes(question.id)
    );

  if (nextRegular) {
    return nextRegular;
  }

  const score =
    calculateAwakeningScore(
      candidateId
    );

  if (
    tieBreaker &&
    score &&
    score.awakenedScore > 42 &&
    score.awakenedScore < 58 &&
    !diagnosisState
      .answeredIds
      .includes(tieBreaker.id)
  ) {
    return tieBreaker;
  }

  return null;
}


// =====================================================
// 覚醒・変身：続行判定
// =====================================================

function evaluateAwakeningProgress() {

  const count =
    getAwakeningAnswerCount();

  if (count < 2) {
    return {
      shouldStop: false,
      reason:
        `覚醒判定を続行（${count}/2問）`
    };
  }

  const score =
    calculateAwakeningScore();

  if (!score) {
    return {
      shouldStop: true,
      reason:
        "覚醒判定対象を確認できませんでした。"
    };
  }

  if (count >= 3) {
    return {
      shouldStop: true,
      reason:
        "タイブレーク質問まで確認したため終了",
      score
    };
  }

  if (
    score.awakenedScore <= 42 ||
    score.awakenedScore >= 58
  ) {
    return {
      shouldStop: true,
      reason:
        `2問で傾向が十分に分かれました（覚醒側 ${score.awakenedScore.toFixed(1)}）`,
      score
    };
  }

  return {
    shouldStop: false,
    reason:
      `基礎形態と覚醒形態が接戦のため追加確認（覚醒側 ${score.awakenedScore.toFixed(1)}）`,
    score
  };
}


// =====================================================
// 覚醒・変身：最終判定
// =====================================================

function evaluateAwakeningResult() {

  const score =
    calculateAwakeningScore();

  if (!score) {
    return null;
  }

  // 2問だけで終わった場合は
  // 42/58を超えているのでそのまま判定。
  // タイブレークまで行った場合は50を境界にする。
  const awakened =
    score.awakenedScore >= 50;

  return {
    ...score,
    awakened,

    finalId:
      awakened
        ? score.rule.awakenedId
        : score.rule.baseId,

    finalName:
      awakened
        ? score.rule.awakenedName
        : score.rule.baseName
  };
}


// =====================================================
// 覚醒・変身：開始
// =====================================================

function startAwakeningStep() {

  setDiagnosisProgress(
    93,
    "最終形態を判定中"
  );

  const candidateId =
    diagnosisState
      .specialDeepResult
      ?.candidate
      ?.id ??
    diagnosisState
      .specialCandidateId;

  if (
    !SPECIAL_AWAKENING_RULES[
      candidateId
    ]
  ) {
    return;
  }

  diagnosisState.route =
    "AWAKENING";

  diagnosisState
    .awakeningCandidateId =
    candidateId;

  diagnosisState
    .awakeningScores = {
      base: 0,
      awakened: 0
    };

  diagnosisState
    .awakeningResult = null;

  diagnosisState.recentThemes = [];
  diagnosisState.recentFormats = [];

  const nextQuestion =
    selectNextAwakeningQuestion();

  if (nextQuestion) {
    renderQuestion(
      nextQuestion
    );
    return;
  }

  showAwakeningSummary();
}


// =====================================================
// 覚醒・変身：終了画面
// =====================================================

function showAwakeningSummary() {

  setDiagnosisProgress(
    99,
    "最終形態の判定が完了しました"
  );

  const progress =
    evaluateAwakeningProgress();

  const result =
    evaluateAwakeningResult();

  diagnosisState
    .awakeningResult =
    result;

  if (result) {
    diagnosisState
      .finalSpecialResult = {
        id: result.finalId,
        name: result.finalName,
        baseCandidateId:
          diagnosisState
            .awakeningCandidateId
      };
  }

  const questionText =
    document.getElementById(
      "questionText"
    );

  const answerButtons =
    document.getElementById(
      "answerButtons"
    );

  const answerStatus =
    document.getElementById(
      "answerStatus"
    );

  const answeredIds =
    diagnosisState
      .answeredIds
      .filter(
        id => id.startsWith("A_")
      );

  questionText.textContent =
    "覚醒・変身形態の判定完了";

  answerButtons.innerHTML = "";

  const resultBox =
    document.createElement(
      "div"
    );

  resultBox.className =
    "analysis-output";

  const lines = [];

  lines.push(
    `回答した覚醒質問：${answeredIds.join(" → ")}`
  );

  lines.push(
    `覚醒質問数：${answeredIds.length}問`
  );

  lines.push(
    `終了理由：${progress.reason}`
  );

  lines.push("");
  lines.push(
    "【覚醒・変身判定】"
  );

  if (result) {

    lines.push(
      `最終形態：${result.finalName}`
    );

    lines.push(
      `覚醒側スコア：${result.awakenedScore.toFixed(1)}`
    );

    lines.push(
      `専用回答：${result.dedicated.toFixed(1)}`
    );

    lines.push(
      `既存キー：${result.keySupport.toFixed(1)}`
    );

    lines.push(
      `性格軸：${result.axisSupport.toFixed(1)}`
    );

    lines.push(
      `一貫性：${result.consistency.toFixed(1)}`
    );

    lines.push("");
    lines.push(
      result.awakened
        ? `${result.rule.baseName}候補から、${result.rule.awakenedName}の傾向が強く出ました。`
        : `${result.rule.awakenedName}ではなく、${result.rule.baseName}の傾向が強く残りました。`
    );

  } else {

    lines.push(
      "覚醒判定を計算できませんでした。"
    );

  }

  resultBox.textContent =
    lines.join("\n");

  answerButtons.appendChild(
    resultBox
  );

  appendFinalResultButton(
    answerButtons
  );

  answerStatus.textContent =
    "覚醒・変身判定が完了しました。最終結果を表示できます。";
}



