// =====================================================
// 最終ノーマル：重要軸の一貫性
// =====================================================

function calculateNormalConsistency(
  monsterId
) {

  const importance =
    NORMAL_AXIS_IMPORTANCE[
      monsterId
    ];

  const targetProfile =
    NORMAL_PROFILES[
      monsterId
    ];

  if (
    !importance ||
    !targetProfile
  ) {
    return 50;
  }

  let sum = 0;
  let count = 0;

  for (
    const axis
    of importance.core
  ) {

    const evidence =
      diagnosisState
        .axisEvidence[axis] ?? 0;

    if (evidence <= 0) {
      continue;
    }

    const rawDirection =
      Math.max(
        -1,
        Math.min(
          1,
          (diagnosisState
            .axisScores[axis] ?? 0) /
          evidence
        )
      );

    const target =
      targetProfile[axis] ?? 50;

    let targetDirection = 0;

    if (target >= 65) {
      targetDirection = 1;
    } else if (target <= 35) {
      targetDirection = -1;
    }

    let axisConsistency;

    if (targetDirection === 0) {
      axisConsistency =
        100 *
        (1 - Math.abs(rawDirection));
    } else {
      axisConsistency =
        50 +
        50 *
        rawDirection *
        targetDirection;
    }

    sum += Math.max(
      0,
      Math.min(
        100,
        axisConsistency
      )
    );

    count++;
  }

  return count > 0
    ? sum / count
    : 50;
}


// =====================================================
// 可変質問の「回答機会」を記録
//
// 例：Aを選べばスライム+3、Bならわたぼう+3という質問を
// 実際に聞かれた場合、両候補に「最大3点を取れる機会があった」
// と記録する。これにより、質問された回数の多い候補だけが
// 生の直接点で有利になる問題を防ぐ。
// =====================================================

function recordScoringOpportunities(
  question
) {

  if (!question?.answers) {
    return;
  }

  const monsterMax = {};
  const signatureMax = {};

  for (const answer of question.answers) {

    for (
      const [monsterId, value]
      of Object.entries(
        answer.monsters ?? {}
      )
    ) {
      monsterMax[monsterId] =
        Math.max(
          monsterMax[monsterId] ?? 0,
          Math.max(0, value)
        );
    }

    for (
      const [signature, value]
      of Object.entries(
        answer.signatures ?? {}
      )
    ) {
      signatureMax[signature] =
        Math.max(
          signatureMax[signature] ?? 0,
          Math.max(0, value)
        );
    }

  }

  for (
    const [monsterId, value]
    of Object.entries(monsterMax)
  ) {
    diagnosisState
      .monsterDirectOpportunities[monsterId] =
        (diagnosisState
          .monsterDirectOpportunities[monsterId] ?? 0) +
        value;
  }

  for (
    const [signature, value]
    of Object.entries(signatureMax)
  ) {
    diagnosisState
      .signatureOpportunities[signature] =
        (diagnosisState
          .signatureOpportunities[signature] ?? 0) +
        value;
  }
}


// =====================================================
// 「実際に獲得した点 / 獲得可能だった点」を0～100へ変換
//
// STEP 9E：未測定(0/0)は「否定」ではなく中立50。
// 1問だけで極端に振れないよう、証拠量が少ないほど50へ縮める。
// =====================================================

function calculateOpportunityCoverage(
  opportunity,
  evidenceScale = 6
) {
  if (opportunity <= 0) return 0;
  return 1 - Math.exp(-opportunity / evidenceScale);
}

function normalizeOpportunityScore(
  actual,
  opportunity,
  evidenceScale = 6
) {
  if (opportunity <= 0) return 50;

  const ratio = Math.max(
    0,
    Math.min(1, actual / opportunity)
  );

  const coverage = calculateOpportunityCoverage(
    opportunity,
    evidenceScale
  );

  const observedScore = ratio * 100;

  return 50 +
    (observedScore - 50) * coverage;
}

// 分岐終了判定用。未測定の中立50は裏付けとして数えない。
function calculateOpportunityEvidenceSupport(
  actual,
  opportunity,
  evidenceScale = 6
) {
  if (opportunity <= 0) return 0;

  const ratio = Math.max(
    0,
    Math.min(1, actual / opportunity)
  );

  const coverage = calculateOpportunityCoverage(
    opportunity,
    evidenceScale
  );

  return ratio * 100 * coverage;
}

function calculateNormalizedMonsterDirectScore(monsterId) {
  const actual = diagnosisState.monsterDirectScores[monsterId] ?? 0;
  const opportunity = diagnosisState.monsterDirectOpportunities[monsterId] ?? 0;
  return normalizeOpportunityScore(actual, opportunity, 6);
}

function calculateNormalizedSignatureScore(signature) {
  const actual = diagnosisState.signatures[signature] ?? 0;
  const opportunity = diagnosisState.signatureOpportunities[signature] ?? 0;
  return normalizeOpportunityScore(actual, opportunity, 5);
}

function getNormalCandidateMeasurement(monsterId) {
  const monster = NORMAL_MONSTERS.find(item => item.id === monsterId);
  const signature = monster?.signature ?? null;

  const directOpportunity =
    diagnosisState.monsterDirectOpportunities[monsterId] ?? 0;
  const signatureOpportunity = signature
    ? diagnosisState.signatureOpportunities[signature] ?? 0
    : 0;

  const directCoverage = calculateOpportunityCoverage(directOpportunity, 6);
  const signatureCoverage = calculateOpportunityCoverage(signatureOpportunity, 5);

  return {
    directOpportunity,
    signatureOpportunity,
    directCoverage,
    signatureCoverage,
    coverage: directCoverage * 0.60 + signatureCoverage * 0.40
  };
}

function calculateMonsterDirectEvidenceSupport(monsterId) {
  return calculateOpportunityEvidenceSupport(
    diagnosisState.monsterDirectScores[monsterId] ?? 0,
    diagnosisState.monsterDirectOpportunities[monsterId] ?? 0,
    6
  );
}

function calculateSignatureEvidenceSupport(signature) {
  return calculateOpportunityEvidenceSupport(
    diagnosisState.signatures[signature] ?? 0,
    diagnosisState.signatureOpportunities[signature] ?? 0,
    5
  );
}


// =====================================================
// 最終ノーマルランキング
// プロフィール70 / 直接点15 / SIGNATURE10 / 一貫性5
//
// 22体はすべて同格。
// レア度・出現率・事前確率による加減点は行わない。
// =====================================================

function calculateFinalNormalRanking() {

  const profile =
    buildCurrentUserProfile();

  return NORMAL_MONSTERS
    .map(monster => {

      const profileScore =
        calculateNormalProfileSimilarity(
          profile,
          monster.id
        );

      const directRaw =
        diagnosisState
          .monsterDirectScores[
            monster.id
          ] ?? 0;

      const signatureRaw =
        diagnosisState
          .signatures[
            monster.signature
          ] ?? 0;

      const directOpportunity =
        diagnosisState
          .monsterDirectOpportunities[
            monster.id
          ] ?? 0;

      const signatureOpportunity =
        diagnosisState
          .signatureOpportunities[
            monster.signature
          ] ?? 0;

      // 可変質問で候補ごとの出題回数が違っても公平になるよう、
      // 生点ではなく「実際に聞かれた回答機会」に対する達成率を使う。
      const directScore =
        calculateNormalizedMonsterDirectScore(
          monster.id
        );

      const signatureScore =
        calculateNormalizedSignatureScore(
          monster.signature
        );

      const consistency =
        calculateNormalConsistency(
          monster.id
        );

      const measurement =
        getNormalCandidateMeasurement(
          monster.id
        );

      const finalScore =
        profileScore * 0.70 +
        directScore * 0.15 +
        signatureScore * 0.10 +
        consistency * 0.05;

      return {
        ...monster,
        profileScore,
        directRaw,
        signatureRaw,
        directOpportunity,
        signatureOpportunity,
        directScore,
        signatureScore,
        consistency,
        measurementCoverage: measurement.coverage,
        finalScore
      };
    })
    .sort(
      (a, b) =>
        b.finalScore -
        a.finalScore
    );
}


// =====================================================
// 最終ノーマル結果
// =====================================================

function getFinalNormalResult() {

  const ranking =
    calculateFinalNormalRanking();

  return ranking[0] ?? null;
}


// =====================================================
// 最終結果を解決
// =====================================================

function resolveFinalResult() {

  const deep =
    diagnosisState
      .specialDeepResult;

  if (
    deep?.passed &&
    deep.candidate
  ) {

    const awakening =
      diagnosisState
        .awakeningResult;

    const specialId =
      awakening?.finalId ??
      deep.candidate.id;

    const specialName =
      awakening?.finalName ??
      deep.candidate.name;

    return {
      id: specialId,
      name: specialName,
      category: "SPECIAL",
      score:
        deep.candidate.deepScore,
      baseCandidateId:
        deep.candidate.id,
      awakeningScore:
        awakening?.awakenedScore ?? null
    };
  }

  const normal =
    getFinalNormalResult();

  return {
    id: normal.id,
    name: normal.name,
    category: "NORMAL",
    score: normal.finalScore,
    profileScore:
      normal.profileScore,
    directRaw:
      normal.directRaw,
    signatureRaw:
      normal.signatureRaw,
    consistency:
      normal.consistency
  };
}



// =====================================================
// 開発用：最終判定の理由を表示
// 公開時に不要なら false に変更するだけで非表示にできます。
// =====================================================

// =====================================================
// STEP 12A：公開モード
// 通常は開発機能を隠す。
// URL末尾に ?dev=1 を付けたときだけ開発機能を表示。
// 例：index.html?dev=1
// =====================================================

const DEVELOPER_MODE =
  (() => {

    try {

      const params =
        new URLSearchParams(
          window.location.search
        );

      return (
        params.get("dev") === "1"
      );

    } catch (error) {

      return false;
    }

  })();


const SHOW_DEVELOPER_RESULT_ANALYSIS =
  DEVELOPER_MODE;


// =====================================================
// 開発用：軸の一致情報を作成
// =====================================================

function getResultAxisMatchDetails(
  profile,
  targetProfile,
  importance
) {

  if (!targetProfile) {
    return [];
  }

  const coreAxes =
    importance?.core ?? [];

  const secondaryAxes =
    importance?.secondary ?? [];

  return AXES.map(axis => {

    const userValue =
      profile[axis] ?? 50;

    const targetValue =
      targetProfile[axis] ?? 50;

    const difference =
      Math.abs(
        userValue - targetValue
      );

    let role = "参考軸";
    let weight = 0.7;

    if (coreAxes.includes(axis)) {
      role = "重要軸";
      weight = 2.0;
    } else if (
      secondaryAxes.includes(axis)
    ) {
      role = "補助軸";
      weight = 1.3;
    }

    const match =
      Math.max(
        0,
        100 - difference
      );

    return {
      axis,
      label:
        AXIS_LABELS[axis],
      userValue,
      targetValue,
      difference,
      match,
      role,
      weight,
      weightedMatch:
        match * weight
    };

  });
}


