function createDebugLine(
  label,
  value,
  className = ""
) {

  const line =
    document.createElement("div");

  line.className =
    `final-debug-line ${className}`.trim();

  const labelElement =
    document.createElement("span");

  labelElement.className =
    "final-debug-label";

  labelElement.textContent = label;

  const valueElement =
    document.createElement("span");

  valueElement.className =
    "final-debug-value";

  valueElement.textContent = value;

  line.appendChild(
    labelElement
  );

  line.appendChild(
    valueElement
  );

  return line;
}


// =====================================================
// 開発用：軸一致リスト
// =====================================================

function createDebugAxisList(
  axisDetails,
  limit = 5
) {

  const wrap =
    document.createElement("div");

  wrap.className =
    "final-debug-axis-list";

  axisDetails
    .slice(0, limit)
    .forEach(detail => {

      const item =
        document.createElement("div");

      item.className =
        "final-debug-axis-item";

      const title =
        document.createElement("div");

      title.className =
        "final-debug-axis-name";

      title.textContent =
        `${detail.label}　${detail.role}`;

      const values =
        document.createElement("div");

      values.className =
        "final-debug-axis-values";

      values.textContent =
        `あなた ${detail.userValue} / タイプ ${detail.targetValue} / 差 ${detail.difference}`;

      item.appendChild(title);
      item.appendChild(values);
      wrap.appendChild(item);

    });

  return wrap;
}


// =====================================================
// 開発用：判定理由テキスト
// コピー用にも使用
// =====================================================

function buildDeveloperResultAnalysisText(
  result,
  profile
) {

  const lines = [];

  lines.push(
    "=== 開発用：最終判定の理由 ==="
  );

  lines.push(
    `最終結果：${result.name} (${result.category})`
  );

  lines.push(
    `回答数：${diagnosisState.questionCount}問`
  );

  if (
    result.category === "NORMAL"
  ) {

    const ranking =
      calculateFinalNormalRanking();

    const first = ranking[0];
    const second = ranking[1];

    lines.push("");
    lines.push(
      "【ノーマル上位5候補】"
    );

    ranking
      .slice(0, 5)
      .forEach((candidate, index) => {

        lines.push(
          `${index + 1}. ${candidate.name}` +
          ` / 総合 ${candidate.finalScore.toFixed(1)}` +
          ` / profile ${candidate.profileScore.toFixed(1)}` +
          ` / direct ${candidate.directScore.toFixed(1)}(` +
          (candidate.directOpportunity > 0
            ? `raw ${candidate.directRaw.toFixed(1)}/${candidate.directOpportunity.toFixed(1)}`
            : "未測定=中立") +
          `)` +
          ` / signature ${candidate.signatureScore.toFixed(1)}(` +
          (candidate.signatureOpportunity > 0
            ? `raw ${candidate.signatureRaw.toFixed(1)}/${candidate.signatureOpportunity.toFixed(1)}`
            : "未測定=中立") +
          `)` +
          ` / measurement ${(candidate.measurementCoverage * 100).toFixed(0)}%` +
          ` / consistency ${candidate.consistency.toFixed(1)}`
        );

      });

    if (first && second) {
      lines.push(
        `1位と2位の差：${(first.finalScore - second.finalScore).toFixed(1)}`
      );
    }

    if (first) {

      lines.push("");
      lines.push(
        "【1位タイプの重要軸】"
      );

      const axisDetails =
        getResultAxisMatchDetails(
          profile,
          NORMAL_PROFILES[first.id],
          NORMAL_AXIS_IMPORTANCE[first.id]
        )
        .filter(detail =>
          detail.role !== "参考軸"
        )
        .sort(
          (a, b) =>
            b.weightedMatch -
            a.weightedMatch
        );

      axisDetails
        .slice(0, 6)
        .forEach(detail => {
          lines.push(
            `${detail.label}: あなた ${detail.userValue}` +
            ` / タイプ ${detail.targetValue}` +
            ` / 差 ${detail.difference}` +
            ` / ${detail.role}`
          );
        });

      lines.push(
        first.directOpportunity > 0
          ? `専用回答の直接点(raw/機会)：${first.directRaw.toFixed(1)}/${first.directOpportunity.toFixed(1)} → ${first.directScore.toFixed(1)}`
          : `専用回答の直接点：未測定 → 中立 ${first.directScore.toFixed(1)}`
      );

      lines.push(
        first.signatureOpportunity > 0
          ? `${first.signature} SIGNATURE(raw/機会)：${first.signatureRaw.toFixed(1)}/${first.signatureOpportunity.toFixed(1)} → ${first.signatureScore.toFixed(1)}`
          : `${first.signature} SIGNATURE：未測定 → 中立 ${first.signatureScore.toFixed(1)}`
      );

      lines.push(
        `専用情報の測定確度：${(first.measurementCoverage * 100).toFixed(0)}%`
      );
    }

  } else {

    const deep =
      diagnosisState
        .specialDeepResult;

    const candidate =
      deep?.candidate ?? null;

    if (candidate) {
      lines.push("");
      lines.push(
        "【SPECIAL判定内訳】"
      );
      lines.push(
        `基礎候補：${candidate.name}`
      );
      lines.push(
        `深掘り適性：${candidate.deepScore.toFixed(1)}`
      );
      lines.push(
        `プロフィール一致：${candidate.profileScore.toFixed(1)}`
      );
      lines.push(
        `固有キー一致：${candidate.keyScore.toFixed(1)}`
      );
      lines.push(
        `SPECIAL専用回答(raw)：${candidate.directRaw.toFixed(1)}`
      );
      lines.push(
        `極端さ：${candidate.extremity.toFixed(1)}`
      );
      lines.push(
        `一貫性：${candidate.consistency.toFixed(1)}`
      );
      lines.push(
        `2位との差：${deep.gap?.toFixed?.(1) ?? "-"}`
      );

      const axisDetails =
        getResultAxisMatchDetails(
          profile,
          SPECIAL_PROFILES[candidate.id],
          SPECIAL_AXIS_IMPORTANCE[candidate.id]
        )
        .filter(detail =>
          detail.role !== "参考軸"
        )
        .sort(
          (a, b) =>
            b.weightedMatch -
            a.weightedMatch
        );

      lines.push("");
      lines.push(
        "【SPECIAL重要軸】"
      );

      axisDetails
        .slice(0, 6)
        .forEach(detail => {
          lines.push(
            `${detail.label}: あなた ${detail.userValue}` +
            ` / タイプ ${detail.targetValue}` +
            ` / 差 ${detail.difference}` +
            ` / ${detail.role}`
          );
        });
    }

    const awakening =
      diagnosisState
        .awakeningResult;

    if (awakening) {
      lines.push("");
      lines.push(
        "【覚醒・変身判定】"
      );
      lines.push(
        `最終形態：${awakening.finalName}`
      );
      lines.push(
        `覚醒側スコア：${awakening.awakenedScore?.toFixed?.(1) ?? "-"}`
      );
    }

    const normalRanking =
      calculateFinalNormalRanking();

    lines.push("");
    lines.push(
      "【ノーマルだった場合の上位3候補】"
    );

    normalRanking
      .slice(0, 3)
      .forEach((candidate, index) => {
        lines.push(
          `${index + 1}. ${candidate.name} ${candidate.finalScore.toFixed(1)}`
        );
      });
  }

  return lines.join("\n");
}


// =====================================================
// 開発用：判定理由の表示セクション
// =====================================================

function createDeveloperResultAnalysisSection(
  result,
  profile
) {

  if (
    !SHOW_DEVELOPER_RESULT_ANALYSIS
  ) {
    return null;
  }

  const details =
    document.createElement("details");

  details.className =
    "final-debug-details";

  const summary =
    document.createElement("summary");

  summary.className =
    "final-debug-summary";

  summary.textContent =
    "開発用：なぜこの結果になった？";

  details.appendChild(summary);

  const body =
    document.createElement("div");

  body.className =
    "final-debug-body";

  const intro =
    document.createElement("p");

  intro.className =
    "final-debug-intro";

  intro.textContent =
    "調整用の内部表示です。『何が判定を押し上げたか』『2位とどれくらい差があるか』を確認できます。";

  body.appendChild(intro);

  if (
    result.category === "NORMAL"
  ) {

    const ranking =
      calculateFinalNormalRanking();

    const first = ranking[0];
    const second = ranking[1];

    body.appendChild(
      createDebugHeading(
        "最終ノーマル候補 TOP5"
      )
    );

    const rankingWrap =
      document.createElement("div");

    rankingWrap.className =
      "final-debug-ranking";

    ranking
      .slice(0, 5)
      .forEach((candidate, index) => {

        const item =
          document.createElement("div");

        item.className =
          `final-debug-rank-item${index === 0 ? " is-first" : ""}`;

        const title =
          document.createElement("div");

        title.className =
          "final-debug-rank-title";

        title.textContent =
          `${index + 1}. ${candidate.name}　総合 ${candidate.finalScore.toFixed(1)}`;

        const breakdown =
          document.createElement("div");

        breakdown.className =
          "final-debug-rank-breakdown";

        const directLabel =
          candidate.directOpportunity > 0
            ? `${candidate.directScore.toFixed(1)} (raw ${candidate.directRaw.toFixed(1)}/${candidate.directOpportunity.toFixed(1)})`
            : `${candidate.directScore.toFixed(1)} (未測定=中立)`;

        const signatureLabel =
          candidate.signatureOpportunity > 0
            ? `${candidate.signatureScore.toFixed(1)} (raw ${candidate.signatureRaw.toFixed(1)}/${candidate.signatureOpportunity.toFixed(1)})`
            : `${candidate.signatureScore.toFixed(1)} (未測定=中立)`;

        breakdown.textContent =
          `プロフィール ${candidate.profileScore.toFixed(1)} / ` +
          `専用回答 ${directLabel} / ` +
          `SIGNATURE ${signatureLabel} / ` +
          `測定確度 ${(candidate.measurementCoverage * 100).toFixed(0)}% / ` +
          `一貫性 ${candidate.consistency.toFixed(1)}`;

        item.appendChild(title);
        item.appendChild(breakdown);
        rankingWrap.appendChild(item);
      });

    body.appendChild(rankingWrap);

    if (first && second) {
      body.appendChild(
        createDebugLine(
          "1位と2位の差",
          `${(first.finalScore - second.finalScore).toFixed(1)}点`,
          (first.finalScore - second.finalScore) < 2
            ? "is-warning"
            : ""
        )
      );
    }

    const formula =
      document.createElement("p");

    formula.className =
      "final-debug-formula";

    formula.textContent =
      "最終スコア = プロフィール70% + 専用回答15% + SIGNATURE10% + 一貫性5%";

    body.appendChild(formula);

    if (first) {

      body.appendChild(
        createDebugHeading(
          `${first.name}になった主な根拠`
        )
      );

      body.appendChild(
        createDebugLine(
          "プロフィール一致",
          first.profileScore.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "専用回答の直接点",
          first.directOpportunity > 0
            ? `${first.directRaw.toFixed(1)}/${first.directOpportunity.toFixed(1)} raw/機会 → ${first.directScore.toFixed(1)}`
            : `未測定 → 中立 ${first.directScore.toFixed(1)}`
        )
      );

      body.appendChild(
        createDebugLine(
          `${first.signature} SIGNATURE`,
          first.signatureOpportunity > 0
            ? `${first.signatureRaw.toFixed(1)}/${first.signatureOpportunity.toFixed(1)} raw/機会 → ${first.signatureScore.toFixed(1)}`
            : `未測定 → 中立 ${first.signatureScore.toFixed(1)}`
        )
      );

      body.appendChild(
        createDebugLine(
          "専用情報の測定確度",
          `${(first.measurementCoverage * 100).toFixed(0)}%`
        )
      );

      body.appendChild(
        createDebugLine(
          "回答の一貫性",
          first.consistency.toFixed(1)
        )
      );

      const importantAxisDetails =
        getResultAxisMatchDetails(
          profile,
          NORMAL_PROFILES[first.id],
          NORMAL_AXIS_IMPORTANCE[first.id]
        )
        .filter(detail =>
          detail.role !== "参考軸"
        )
        .sort(
          (a, b) =>
            b.weightedMatch -
            a.weightedMatch
        );

      body.appendChild(
        createDebugHeading(
          "よく一致した重要軸"
        )
      );

      body.appendChild(
        createDebugAxisList(
          importantAxisDetails,
          5
        )
      );

      const mismatches =
        [...importantAxisDetails]
          .sort(
            (a, b) =>
              b.difference -
              a.difference
          );

      body.appendChild(
        createDebugHeading(
          "逆にズレが大きい重要軸"
        )
      );

      body.appendChild(
        createDebugAxisList(
          mismatches,
          3
        )
      );
    }

  } else {

    const deep =
      diagnosisState
        .specialDeepResult;

    const candidate =
      deep?.candidate ?? null;

    body.appendChild(
      createDebugHeading(
        "SPECIAL判定の内訳"
      )
    );

    if (candidate) {

      body.appendChild(
        createDebugLine(
          "基礎SPECIAL候補",
          candidate.name
        )
      );

      body.appendChild(
        createDebugLine(
          "深掘り適性",
          candidate.deepScore.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "プロフィール一致",
          candidate.profileScore.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "固有キー一致",
          candidate.keyScore.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "SPECIAL専用回答",
          `${candidate.directRaw.toFixed(1)} raw`
        )
      );

      body.appendChild(
        createDebugLine(
          "性格の極端さ",
          candidate.extremity.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "回答の一貫性",
          candidate.consistency.toFixed(1)
        )
      );

      body.appendChild(
        createDebugLine(
          "2位SPECIALとの差",
          `${deep.gap?.toFixed?.(1) ?? "-"}点`
        )
      );

      const specialAxisDetails =
        getResultAxisMatchDetails(
          profile,
          SPECIAL_PROFILES[candidate.id],
          SPECIAL_AXIS_IMPORTANCE[candidate.id]
        )
        .filter(detail =>
          detail.role !== "参考軸"
        )
        .sort(
          (a, b) =>
            b.weightedMatch -
            a.weightedMatch
        );

      body.appendChild(
        createDebugHeading(
          "SPECIAL候補と一致した重要軸"
        )
      );

      body.appendChild(
        createDebugAxisList(
          specialAxisDetails,
          6
        )
      );
    }

    const awakening =
      diagnosisState
        .awakeningResult;

    if (awakening) {

      body.appendChild(
        createDebugHeading(
          "覚醒・変身判定"
        )
      );

      body.appendChild(
        createDebugLine(
          "最終形態",
          awakening.finalName
        )
      );

      body.appendChild(
        createDebugLine(
          "覚醒側スコア",
          awakening.awakenedScore?.toFixed?.(1) ?? "-"
        )
      );
    }

    const normalRanking =
      calculateFinalNormalRanking();

    body.appendChild(
      createDebugHeading(
        "SPECIALでなかった場合のノーマル候補"
      )
    );

    const fallback =
      document.createElement("div");

    fallback.className =
      "final-debug-ranking";

    normalRanking
      .slice(0, 3)
      .forEach((candidate, index) => {

        const item =
          document.createElement("div");

        item.className =
          "final-debug-rank-item";

        item.textContent =
          `${index + 1}. ${candidate.name}　${candidate.finalScore.toFixed(1)}`;

        fallback.appendChild(item);
      });

    body.appendChild(fallback);
  }

  const copyButton =
    document.createElement("button");

  copyButton.type = "button";
  copyButton.className =
    "final-debug-copy-button";

  copyButton.textContent =
    "判定データをコピー";

  copyButton.addEventListener(
    "click",
    async () => {

      const text =
        buildDeveloperResultAnalysisText(
          result,
          profile
        );

      try {
        await navigator.clipboard.writeText(
          text
        );
        copyButton.textContent =
          "コピーしました！";
      } catch (error) {
        console.error(error);
        copyButton.textContent =
          "コピーできませんでした";
      }

      setTimeout(
        () => {
          copyButton.textContent =
            "判定データをコピー";
        },
        1600
      );
    }
  );

  body.appendChild(copyButton);
  details.appendChild(body);

  return details;
}


// =====================================================
// 結果画像候補
// SPECIAL画像は英字ID / 日本語名の両方を試す
// =====================================================

function getResultImageCandidates(
  result
) {

  const normal =
    NORMAL_MONSTERS.find(
      monster =>
        monster.id === result.id
    );

  if (normal?.image) {
    return [normal.image];
  }

  const meta =
    RESULT_TYPE_META[
      result.id
    ];

  const name =
    meta?.name ?? result.name;

  return [
    `images/${result.id}.png`,
    `images/${name}.png`,
    `images/${result.id}.jpg`,
    `images/${name}.jpg`
  ];
}



