function getResultVisualTheme(result) {
  return RESULT_VISUAL_THEMES[result.id] ?? {
    accent: result.category === "SPECIAL" ? "#c39bff" : "#84cfff",
    accent2: result.category === "SPECIAL" ? "#ffd47c" : "#bce8ff",
    bg1: "#202533",
    bg2: "#181b22",
    soft: "rgba(132,207,255,0.16)",
    glow: "rgba(132,207,255,0.24)"
  };
}


function applyResultVisualTheme(card, result) {
  const theme = getResultVisualTheme(result);

  card.style.setProperty("--result-accent", theme.accent);
  card.style.setProperty("--result-accent2", theme.accent2);
  card.style.setProperty("--result-bg1", theme.bg1);
  card.style.setProperty("--result-bg2", theme.bg2);
  card.style.setProperty("--result-accent-soft", theme.soft);
  card.style.setProperty("--result-glow", theme.glow);

  card.dataset.resultId = result.id;

  if (result.category === "SPECIAL") {
    card.classList.add("is-special");
  }
}


function createResultTraitTags(profile) {
  const wrap = document.createElement("div");
  wrap.className = "final-trait-tags";

  AXES
    .map(axis => ({ axis, value: profile[axis] ?? 50 }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 3)
    .forEach(item => {
      const tag = document.createElement("span");
      tag.className = "final-trait-tag";
      tag.textContent = `${AXIS_LABELS[item.axis]} ${item.value}`;
      wrap.appendChild(tag);
    });

  return wrap;
}


function buildDiagnosisShareText(result, meta, profile) {
  const topAxes = AXES
    .map(axis => ({ axis, value: profile[axis] ?? 50 }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 3)
    .map(item => `${AXIS_LABELS[item.axis]} ${item.value}`)
    .join(" / ");

  const scoreLabel =
    result.category === "SPECIAL"
      ? `SPECIAL適性 ${result.score.toFixed(1)}`
      : `タイプ一致度 ${result.score.toFixed(1)}`;

  const subtype =
    buildDynamicSubtype(
      result,
      profile
    );

  const lines = [
    `【モンスター性格診断】`,
    `結果：${meta.name}`,
    `サブタイプ：${subtype.label}`,
    meta.catchphrase,
    `${scoreLabel} / ${topAxes}`,
    `#モンスター性格診断 #非公式ファンメイド`
  ];

  if (
    typeof location !== "undefined" &&
    /^https?:$/i.test(location.protocol)
  ) {
    lines.push(location.href);
  }

  return lines.join("\n");
}


async function copyTextWithFallback(text) {
  if (
    navigator.clipboard &&
    typeof navigator.clipboard.writeText === "function"
  ) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (error) {
      // file:// 等では失敗する場合があるため下へ
    }
  }

  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  textarea.style.pointerEvents = "none";
  document.body.appendChild(textarea);
  textarea.select();

  let copied = false;

  try {
    copied = document.execCommand("copy");
  } catch (error) {
    copied = false;
  }

  textarea.remove();
  return copied;
}


async function shareDiagnosisResult(result, meta, profile) {
  const text = buildDiagnosisShareText(result, meta, profile);
  const status = document.getElementById("answerStatus");

  if (
    navigator.share &&
    typeof navigator.share === "function"
  ) {
    try {
      await navigator.share({
        title: `モンスター性格診断：${meta.name}`,
        text
      });

      status.textContent = "共有メニューを開きました。";
      return;
    } catch (error) {
      if (error?.name === "AbortError") {
        status.textContent = "共有をキャンセルしました。";
        return;
      }
    }
  }

  const copied = await copyTextWithFallback(text);
  status.textContent = copied
    ? "結果文をクリップボードへコピーしました。"
    : "結果文のコピーに失敗しました。";
}


async function copyDiagnosisResult(result, meta, profile) {
  const text = buildDiagnosisShareText(result, meta, profile);
  const copied = await copyTextWithFallback(text);
  const status = document.getElementById("answerStatus");

  status.textContent = copied
    ? "結果文をコピーしました！"
    : "コピーに失敗しました。";
}


