const SHARE_CARD_IMAGE_DATA = {"beast_nergel":"data:image/webp;base64,","bomb_rock":"data:image/webp;base64,","dark_dream":"data:image/webp;base64,","dark_god_rhapthorne":"data:image/webp;base64,","deathmore":"data:image/webp;base64,","demon_king_mildrath":"data:image/webp;base64,","demon_king_orgo":"data:image/webp;base64,","despisaro":"data:image/webp;base64,","dracky":"data:image/webp;base64,","dragon":"data:image/webp;base64,","dragonlord":"data:image/webp;base64,","elgios":"data:image/webp;base64,","estark":"data:image/webp;base64,","fallen_elgios":"data:image/webp;base64,","ghost":"data:image/webp;base64,","god":"data:image/webp;base64,","golem":"data:image/webp;base64,","great_demon_king_deathmore":"data:image/webp;base64,","great_dragon":"data:image/webp;base64,","hammerhood":"data:image/webp;base64,","healslime":"data:image/webp;base64,","killer_panther":"data:image/webp;base64,","killing_machine":"data:image/webp;base64,","king_slime":"data:image/webp;base64,","liquid_metal_slime":"data:image/webp;base64,","maou_shadow":"data:image/webp;base64,","mechaburn":"data:image/webp;base64,","metal_king":"data:image/webp;base64,","mildrath":"data:image/webp;base64,","moomon":"data:image/webp;base64,","nergel":"data:image/webp;base64,","nizelpha":"data:image/webp;base64,","onehorn_rabbit":"data:image/webp;base64,","orgo":"data:image/webp;base64,","rhapthorne":"data:image/webp;base64,","ryuou":"data:image/webp;base64,","shido":"data:image/webp;base64,","slime":"data:image/webp;base64,","slime_knight":"data:image/webp;base64,","urnoga":"data:image/webp;base64,","wandering_armor":"data:image/webp;base64,","warubou":"data:image/webp;base64,","watabou":"data:image/webp;base64,","zoma":"data:image/webp;base64,"};

function drawWrappedCanvasText(
  ctx,
  text,
  x,
  y,
  maxWidth,
  lineHeight,
  maxLines = 3
) {
  let line = "";
  let lines = [];

  for (const char of String(text)) {
    const test = line + char;

    if (
      ctx.measureText(test).width > maxWidth &&
      line
    ) {
      lines.push(line);
      line = char;

      if (lines.length >= maxLines - 1) {
        break;
      }
    } else {
      line = test;
    }
  }

  if (line && lines.length < maxLines) {
    lines.push(line);
  }

  lines.forEach((value, index) => {
    ctx.fillText(value, x, y + lineHeight * index);
  });

  return y + lineHeight * lines.length;
}



async function loadShareCardEmbeddedImage(
  result
) {

  const dataUrl =
    SHARE_CARD_IMAGE_DATA[
      result.id
    ];

  if (!dataUrl) {
    return null;
  }


  return await new Promise(
    resolve => {

      const image =
        new Image();

      image.onload =
        () => resolve(image);

      image.onerror =
        () => resolve(null);

      image.src = dataUrl;

    }
  );
}


function drawShareCardCanvas(
  canvas,
  result,
  meta,
  profile,
  shareImage = null
) {
  const ctx = canvas.getContext("2d");
  const theme = getResultVisualTheme(result);
  const width = canvas.width;
  const height = canvas.height;

  ctx.clearRect(0, 0, width, height);

  const gradient = ctx.createLinearGradient(0, 0, width, height);
  gradient.addColorStop(0, theme.bg1);
  gradient.addColorStop(1, theme.bg2);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);

  const glow = ctx.createRadialGradient(
    width * 0.82,
    height * 0.12,
    20,
    width * 0.82,
    height * 0.12,
    width * 0.55
  );
  glow.addColorStop(0, theme.soft);
  glow.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);

  ctx.strokeStyle = theme.accent;
  ctx.lineWidth = 3;
  ctx.strokeRect(28, 28, width - 56, height - 56);

  ctx.fillStyle = theme.accent;
  ctx.font = "700 22px sans-serif";
  ctx.fillText(
    result.category === "SPECIAL" ? "SPECIAL TYPE" : "MONSTER TYPE",
    72,
    92
  );

  ctx.fillStyle = "#ffffff";
  ctx.font = "700 58px sans-serif";
  ctx.fillText(meta.name, 72, 174);

  const subtype =
    buildDynamicSubtype(
      result,
      profile
    );

  ctx.fillStyle = theme.accent;
  ctx.font = "700 20px sans-serif";
  ctx.fillText(
    `サブタイプ：${subtype.label}`,
    72,
    211
  );

  ctx.fillStyle = theme.accent2;
  ctx.font = "700 27px sans-serif";
  const afterCatch = drawWrappedCanvasText(
    ctx,
    meta.catchphrase,
    72,
    250,
    650,
    38,
    3
  );

  if (
    shareImage &&
    shareImage.complete &&
    shareImage.naturalWidth > 0
  ) {

    const boxX = 790;
    const boxY = 105;
    const boxW = 320;
    const boxH = 330;

    const scale =
      Math.min(
        boxW /
          shareImage.naturalWidth,
        boxH /
          shareImage.naturalHeight
      );

    const drawW =
      shareImage.naturalWidth *
      scale;

    const drawH =
      shareImage.naturalHeight *
      scale;


    ctx.save();

    ctx.shadowColor =
      theme.glow;

    ctx.shadowBlur = 32;

    ctx.drawImage(
      shareImage,
      boxX +
        (boxW - drawW) / 2,
      boxY +
        (boxH - drawH) / 2,
      drawW,
      drawH
    );

    ctx.restore();

  }

  const topAxes = AXES
    .map(axis => ({ axis, value: profile[axis] ?? 50 }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 3);

  let chipX = 72;
  const chipY = Math.max(338, afterCatch + 28);

  ctx.font = "700 19px sans-serif";

  topAxes.forEach(item => {
    const label = `${AXIS_LABELS[item.axis]} ${item.value}`;
    const chipW = ctx.measureText(label).width + 32;

    ctx.fillStyle = "rgba(255,255,255,0.10)";
    ctx.beginPath();
    if (ctx.roundRect) {
      ctx.roundRect(chipX, chipY, chipW, 42, 21);
    } else {
      ctx.rect(chipX, chipY, chipW, 42);
    }
    ctx.fill();

    ctx.fillStyle = "#ffffff";
    ctx.fillText(label, chipX + 16, chipY + 28);
    chipX += chipW + 10;
  });

  const shareRadarItems =
    getShareCardRadarItems(
      profile
    );

  drawRadarChartOnCanvas(
    ctx,
    shareRadarItems,
    {
      centerX: 266,
      centerY: 502,
      radius: 82,
      labelRadius: 119,
      theme,
      showGuides: false
    }
  );

  ctx.fillStyle = theme.accent2;
  ctx.font = "700 20px sans-serif";
  ctx.fillText(
    "8軸プロフィール",
    408,
    430
  );

  const scoreText =
    result.category === "SPECIAL"
      ? `SPECIAL適性 ${result.score.toFixed(1)}`
      : `タイプ一致度 ${result.score.toFixed(1)}`;

  ctx.fillStyle = "#ffffff";
  ctx.font = "700 28px sans-serif";
  ctx.fillText(scoreText, 408, 474);

  ctx.fillStyle = "rgba(255,255,255,0.82)";
  ctx.font = "18px sans-serif";
  ctx.fillText(
    `回答数 ${diagnosisState.questionCount}問`,
    408,
    515
  );

  ctx.fillStyle = "rgba(255,255,255,0.68)";
  ctx.font = "17px sans-serif";
  drawWrappedCanvasText(
    ctx,
    "外側ほど傾向が強い / 非公式ファンメイド診断",
    408,
    552,
    295,
    24,
    2
  );
}


async function canvasToBlobSafe(canvas) {

  // 通常は toBlob を使用
  if (
    typeof canvas.toBlob === "function"
  ) {

    try {

      const blob =
        await new Promise(
          (resolve, reject) => {

            canvas.toBlob(
              value => {

                if (value) {
                  resolve(value);
                } else {
                  reject(
                    new Error(
                      "PNG生成に失敗しました"
                    )
                  );
                }

              },
              "image/png"
            );

          }
        );

      return blob;

    } catch (error) {
      // dataURL方式へフォールバック
    }

  }


  // 一部ブラウザ向けフォールバック
  const dataUrl =
    canvas.toDataURL(
      "image/png"
    );

  const response =
    await fetch(dataUrl);

  return await response.blob();
}


async function downloadDiagnosisShareCard(
  result,
  meta,
  profile
) {

  const createCanvas =
    () => {

      const canvas =
        document.createElement(
          "canvas"
        );

      canvas.width = 1200;
      canvas.height = 630;

      return canvas;
    };


  // STEP 12E:
  // 結果画面に表示中の外部画像ではなく、
  // app.js内の安全なData URL画像を使う。
  // これにより file:// でもCanvasが汚染されない。
  const shareImage =
    await loadShareCardEmbeddedImage(
      result
    );


  const canvas =
    createCanvas();


  drawShareCardCanvas(
    canvas,
    result,
    meta,
    profile,
    shareImage
  );


  const blob =
    await canvasToBlobSafe(
      canvas
    );


  if (!blob) {

    throw new Error(
      "PNG生成に失敗しました"
    );

  }


  const url =
    URL.createObjectURL(
      blob
    );

  const anchor =
    document.createElement(
      "a"
    );


  anchor.href = url;

  anchor.download =
    `monster_type_${result.id}.png`;

  anchor.rel =
    "noopener";


  document.body.appendChild(
    anchor
  );

  anchor.click();

  anchor.remove();


  setTimeout(
    () =>
      URL.revokeObjectURL(
        url
      ),
    5000
  );


  document
    .getElementById(
      "answerStatus"
    )
    .textContent =
      shareImage
        ? "モンスター画像入りの結果カードPNGを作成しました。"
        : "結果カードPNGを作成しました。";

}

function createFinalShareActions(
  result,
  meta,
  profile
) {
  const wrap = document.createElement("div");
  wrap.className = "final-share-actions";

  const shareButton = document.createElement("button");
  shareButton.className = "answer-button result-action-button";
  shareButton.textContent = "結果を共有";
  shareButton.addEventListener("click", () => {
    shareDiagnosisResult(result, meta, profile);
  });

  const copyButton = document.createElement("button");
  copyButton.className = "answer-button result-action-button";
  copyButton.textContent = "結果文をコピー";
  copyButton.addEventListener("click", () => {
    copyDiagnosisResult(result, meta, profile);
  });

  const cardButton = document.createElement("button");
  cardButton.className = "answer-button result-action-button";
  cardButton.textContent = "結果カードPNG";
  cardButton.addEventListener("click", () => {
    downloadDiagnosisShareCard(result, meta, profile)
      .catch(() => {
        document.getElementById("answerStatus").textContent =
          "結果カードPNGの作成に失敗しました。ブラウザを更新してもう一度お試しください。";
      });
  });

  wrap.appendChild(shareButton);
  wrap.appendChild(copyButton);
  wrap.appendChild(cardButton);

  return wrap;
}

