// =====================================================
// 結果画像を候補順に読み込む
// 見つからなければ画像枠だけ非表示
// =====================================================

function attachResultImage(
  container,
  result
) {

  const candidates =
    getResultImageCandidates(
      result
    );

  if (
    !candidates ||
    candidates.length === 0
  ) {
    return;
  }

  const image =
    document.createElement(
      "img"
    );

  image.className =
    "final-result-image";

  image.alt =
    `${result.name}のイメージ`;

  let index = 0;

  image.addEventListener(
    "error",
    () => {
      index++;

      if (
        index < candidates.length
      ) {
        image.src =
          candidates[index];
      } else {
        container.style.display =
          "none";
      }
    }
  );

  image.src = candidates[0];

  container.appendChild(
    image
  );
}


// =====================================================
// 16軸バーを作成
// =====================================================

function createFinalAxisGrid(
  profile
) {

  const grid =
    document.createElement(
      "div"
    );

  grid.className =
    "final-axis-grid";

  AXES.forEach(axis => {

    const value =
      profile[axis] ?? 50;

    const row =
      document.createElement(
        "div"
      );

    row.className =
      "final-axis-row";

    const label =
      document.createElement(
        "div"
      );

    label.className =
      "final-axis-label";

    const labelName =
      document.createElement(
        "span"
      );

    labelName.textContent =
      AXIS_LABELS[axis];

    const labelValue =
      document.createElement(
        "span"
      );

    labelValue.textContent =
      String(value);

    label.appendChild(
      labelName
    );

    label.appendChild(
      labelValue
    );

    const track =
      document.createElement(
        "div"
      );

    track.className =
      "final-axis-track";

    const fill =
      document.createElement(
        "div"
      );

    fill.className =
      "final-axis-fill";

    fill.style.width =
      `${value}%`;

    track.appendChild(fill);
    row.appendChild(label);
    row.appendChild(track);
    grid.appendChild(row);
  });

  return grid;
}



