const SUBTYPE_AXIS_NOUN_PHRASES = {
  BOLD:  "必要なときに踏み出せる大胆さ",
  CAUT:  "一度確かめてから動く慎重さ",
  INT:   "物事を整理して考える知略",
  ADAPT: "状況に合わせる柔軟さ",
  CALM:  "慌てにくい冷静さ",
  EMOT:  "大切なものへ強く反応する感情の豊かさ",
  AGGR:  "問題へ正面から向き合う突破力",
  PATI:  "時間がかかっても待てる忍耐力",
  GRIT:  "簡単には手放さない粘り強さ",
  CONV:  "自分の筋を大切にする責任感",
  AMBI:  "さらに上を目指す向上心",
  LEAD:  "必要なときに方向を示す主導性",
  INDEP: "周囲に流されすぎない独立心",
  CURI:  "未知へ目を向ける好奇心",
  PLAY:  "余白を楽しめる遊び心",
  COOP:  "人と歩調を合わせる協調性"
};


function calculateSubtypeTraitScore(
  definition,
  profile,
  referenceProfile,
  ranking
) {

  let axisTotal = 0;
  let axisWeight = 0;
  let deltaTotal = 0;

  for (
    const [axis, weight]
    of Object.entries(
      definition.axes
    )
  ) {

    const userValue =
      profile[axis] ?? 50;

    axisTotal +=
      userValue * weight;

    axisWeight += weight;

    if (referenceProfile) {
      deltaTotal +=
        (userValue -
          (referenceProfile[axis] ?? 50)) *
        weight;
    }
  }

  const axisScore =
    axisWeight > 0
      ? axisTotal / axisWeight
      : 50;

  const averageDelta =
    axisWeight > 0
      ? deltaTotal / axisWeight
      : 0;

  // 1位はメインタイプなので、サブタイプ判定では2～5位をやや強く見る。
  const rankWeights =
    [0.18, 1.00, 0.72, 0.52, 0.36];

  let candidateSupport = 0;
  let candidateMax = 0;

  ranking
    .slice(0, 5)
    .forEach(
      (candidate, index) => {

        const weight =
          rankWeights[index] ?? 0;

        candidateMax += weight;

        if (
          definition
            .candidates
            .includes(candidate.id)
        ) {
          candidateSupport += weight;
        }
      }
    );

  const candidateScore =
    candidateMax > 0
      ? candidateSupport /
        candidateMax * 100
      : 0;

  // メインタイプ平均との差。
  // そのタイプの中でも「特に何が強いか」をサブタイプへ反映。
  const deltaScore =
    Math.max(
      0,
      Math.min(
        100,
        50 + averageDelta * 2.2
      )
    );

  const total =
    axisScore * 0.52 +
    candidateScore * 0.30 +
    deltaScore * 0.18;

  return {
    ...definition,
    score: total,
    axisScore,
    candidateScore,
    averageDelta
  };
}


function getSubtypeBaseAxes(
  result,
  profile,
  primaryTrait = null
) {

  const importance =
    NORMAL_AXIS_IMPORTANCE[
      result.id
    ];

  const primaryAxes =
    new Set(
      Object.keys(
        primaryTrait?.axes ?? {}
      )
    );

  if (importance) {

    // メインタイプの「土台」はまず重要軸を優先。
    // サブタイプですでに強調した軸は補助軸側では重ねすぎない。
    const selected = [];

    importance.core
      .slice()
      .sort(
        (a, b) =>
          (profile[b] ?? 50) -
          (profile[a] ?? 50)
      )
      .forEach(axis => {
        if (selected.length < 2) {
          selected.push(axis);
        }
      });

    importance.secondary
      .filter(
        axis =>
          !primaryAxes.has(axis)
      )
      .sort(
        (a, b) =>
          (profile[b] ?? 50) -
          (profile[a] ?? 50)
      )
      .forEach(axis => {
        if (
          selected.length < 3 &&
          !selected.includes(axis)
        ) {
          selected.push(axis);
        }
      });

    // それでも足りない場合だけ、除外した補助軸から補完。
    importance.secondary
      .slice()
      .sort(
        (a, b) =>
          (profile[b] ?? 50) -
          (profile[a] ?? 50)
      )
      .forEach(axis => {
        if (
          selected.length < 3 &&
          !selected.includes(axis)
        ) {
          selected.push(axis);
        }
      });

    return selected
      .map(axis => ({
        axis,
        value:
          profile[axis] ?? 50
      }));
  }

  const reference =
    getResultReferenceProfile(
      result.id
    );

  if (!reference) {
    return [];
  }

  return AXES
    .slice()
    .filter(
      axis =>
        !primaryAxes.has(axis)
    )
    .sort(
      (a, b) =>
        (reference[b] ?? 50) -
        (reference[a] ?? 50)
    )
    .slice(0, 3)
    .map(axis => ({
      axis,
      value:
        profile[axis] ?? 50
    }));
}


function getSubtypeIntensityWord(
  primaryTrait,
  referenceProfile
) {

  const delta =
    primaryTrait
      .averageDelta ?? 0;

  if (
    primaryTrait.axisScore >= 88 ||
    delta >= 22
  ) {
    return "かなり";
  }

  if (
    primaryTrait.axisScore >= 78 ||
    delta >= 12
  ) {
    return "はっきり";
  }

  if (
    primaryTrait.axisScore >= 68
  ) {
    return "やや";
  }

  return "ほんのり";
}


function buildDynamicSubtype(
  result,
  profile,
  rankingOverride = null
) {

  const ranking =
    rankingOverride ??
    calculateFinalNormalRanking();

  const referenceProfile =
    getResultReferenceProfile(
      result.id
    );

  const scoredTraits =
    SUBTYPE_TRAIT_DEFINITIONS
      .map(
        definition =>
          calculateSubtypeTraitScore(
            definition,
            profile,
            referenceProfile,
            ranking
          )
      )
      .sort(
        (a, b) =>
          b.score - a.score
      );

  const primary =
    scoredTraits[0] ??
    SUBTYPE_TRAIT_DEFINITIONS[0];

  // 主軸がほぼ同じテーマは避け、文章用の第2テーマを選ぶ。
  const primaryAxes =
    new Set(
      Object.keys(
        primary.axes ?? {}
      )
    );

  const secondary =
    scoredTraits
      .slice(1)
      .find(trait => {

        const overlap =
          Object.keys(
            trait.axes ?? {}
          )
            .filter(
              axis =>
                primaryAxes.has(axis)
            )
            .length;

        return (
          overlap <= 2 &&
          trait.score >= 60
        );
      }) ??
    scoredTraits[1] ??
    null;

  const intensity =
    getSubtypeIntensityWord(
      primary,
      referenceProfile
    );

  const baseAxes =
    getSubtypeBaseAxes(
      result,
      profile,
      primary
    );

  const basePhrases =
    baseAxes
      .map(
        item =>
          SUBTYPE_AXIS_NOUN_PHRASES[
            item.axis
          ]
      )
      .filter(Boolean);

  let baseSentence = "";

  if (basePhrases.length >= 3) {

    baseSentence =
      `基本的には、${basePhrases[0]}と${basePhrases[1]}が土台にあり、${basePhrases[2]}も持っています。`;

  } else if (
    basePhrases.length === 2
  ) {

    baseSentence =
      `基本的には、${basePhrases[0]}と${basePhrases[1]}が土台になっています。`;

  } else if (
    basePhrases.length === 1
  ) {

    baseSentence =
      `基本的には、${basePhrases[0]}が強く出ています。`;
  }

  const text = [
    `${RESULT_TYPE_META[result.id]?.name ?? result.name}タイプの中でも、${intensity}${primary.lead}タイプです。`,
    baseSentence,
    primary.sentence
  ]
    .filter(Boolean)
    .join(" ");

  return {
    label: primary.label,
    displayName:
      `${primary.label} ${RESULT_TYPE_META[result.id]?.name ?? result.name}`,
    text,
    primary,
    secondary,
    ranking:
      ranking.slice(0, 5)
  };
}


