// サブタイプ表示
// =====================================================

function createDynamicSubtypeSection(
  result,
  profile
) {

  const subtype =
    buildDynamicSubtype(
      result,
      profile
    );

  const wrap =
    document.createElement(
      "section"
    );

  wrap.className =
    "final-subtype-section";

  const badge =
    document.createElement(
      "div"
    );

  badge.className =
    "final-subtype-label";

  badge.textContent =
    `サブタイプ：${subtype.label}`;

  const text =
    document.createElement(
      "p"
    );

  text.className =
    "final-subtype-text";

  text.textContent =
    subtype.text;

  wrap.appendChild(badge);
  wrap.appendChild(text);

  return {
    element: wrap,
    subtype
  };
}


// =====================================================
// STEP 10A：テストプレイヤー用フィードバック
// =====================================================

const DIAGNOSIS_FEEDBACK_STORAGE_KEY =
  "dqMonsterDiagnosisFeedbackV1";


