// =====================================================
// 軸の重要度を取得
// =====================================================

function getNormalAxisWeight(monsterId, axis) {

  const importance =
    NORMAL_AXIS_IMPORTANCE[monsterId];

  if (!importance) {
    return 0.7;
  }

  if (importance.core.includes(axis)) {
    return 2.0;
  }

  if (importance.secondary.includes(axis)) {
    return 1.3;
  }

  return 0.7;
}


// =====================================================
// 1体とのプロフィール一致度
// =====================================================

function calculateNormalProfileSimilarity(
  userProfile,
  monsterId
) {

  const monsterProfile =
    NORMAL_PROFILES[monsterId];

  if (!monsterProfile) {
    return 0;
  }

  let weightedDistance = 0;
  let totalWeight = 0;

  for (const axis of AXES) {

    const userValue =
      Number(userProfile[axis]);

    const monsterValue =
      Number(monsterProfile[axis]);

    if (
      !Number.isFinite(userValue) ||
      !Number.isFinite(monsterValue)
    ) {
      continue;
    }

    const weight =
      getNormalAxisWeight(
        monsterId,
        axis
      );

    const distance =
      Math.abs(
        userValue - monsterValue
      );

    weightedDistance +=
      distance * weight;

    totalWeight += weight;
  }

  if (totalWeight === 0) {
    return 0;
  }

  const averageDistance =
    weightedDistance / totalWeight;

  const similarity =
    100 - averageDistance;

  return Math.max(
    0,
    Math.min(100, similarity)
  );
}


// =====================================================
// ノーマル22体を順位付け
// =====================================================

function rankNormalMonsters(userProfile) {

  const ranking =
    NORMAL_MONSTERS.map(monster => {

      return {
        id: monster.id,
        name: monster.name,
        signature:
          monster.signature,

        similarity:
          calculateNormalProfileSimilarity(
            userProfile,
            monster.id
          )
      };

    });

  ranking.sort(
    (a, b) =>
      b.similarity - a.similarity
  );

  return ranking;
}


