// -----------------------------------------------------

function createInitialState() {
  const axisScores = {};
  const axisEvidence = {};

  for (const axis of AXES) {
    axisScores[axis] = 0;
    axisEvidence[axis] = 0;
  }

  return {
    axisScores,
    axisEvidence,

    flags: {},
    signatures: {},

    // 可変質問で「聞かれた回数」が候補ごとに違っても
    // 公平に比較できるよう、獲得可能だった最大点も記録する。
    signatureOpportunities: {},
    monsterDirectOpportunities: {},

    monsterDirectScores: {},
    specialDirectScores: {},

    specialGate: null,
    specialCandidateId: null,

    awakeningScores: {
      base: 0,
      awakened: 0
    },
    awakeningCandidateId: null,
    awakeningResult: null,

    answeredIds: [],

    recentThemes: [],
    recentFormats: [],

    questionCount: 0,

    displayProgress: 0,

    route: "CORE"
  };
}


