const ALL_NORMAL_BRANCH_QUESTIONS = [
  ...NORMAL_BRANCH_QUESTIONS,
  ...NORMAL_PAIR_QUESTIONS,
  ...NORMAL_EXPLORATION_QUESTIONS
];

const NORMAL_BRANCH_QUESTION_IDS =
  new Set(
    ALL_NORMAL_BRANCH_QUESTIONS
      .map(question => question.id)
  );


function getNormalBranchQuestionById(
  id
) {
  return ALL_NORMAL_BRANCH_QUESTIONS
    .find(
      question => question.id === id
    ) ?? null;
}


function findNormalPairQuestion(
  firstId,
  secondId
) {

  if (!firstId || !secondId) {
    return null;
  }

  return NORMAL_PAIR_QUESTIONS.find(
    question =>
      !diagnosisState
        .answeredIds
        .includes(question.id) &&
      question.pair.includes(firstId) &&
      question.pair.includes(secondId)
  ) ?? null;
}


// =====================================================
// STEP 9E：未測定候補を公平に確認するための質問選択
// =====================================================

function getQuestionMeasurementPotential(question, monsterId) {
  const monster = NORMAL_MONSTERS.find(item => item.id === monsterId);
  if (!monster || !question?.answers) return 0;

  let directMax = 0;
  let signatureMax = 0;

  for (const answer of question.answers) {
    directMax = Math.max(
      directMax,
      Math.max(0, answer.monsters?.[monsterId] ?? 0)
    );
    signatureMax = Math.max(
      signatureMax,
      Math.max(0, answer.signatures?.[monster.signature] ?? 0)
    );
  }

  return directMax + signatureMax * 0.8;
}

function selectNormalMeasurementQuestion(candidateId, rivalId = null) {
  if (!candidateId) return null;

  let bestQuestion = null;
  let bestScore = -Infinity;
  const lastFormat = diagnosisState.recentFormats.at(-1);

  for (const question of ALL_NORMAL_BRANCH_QUESTIONS) {
    if (diagnosisState.answeredIds.includes(question.id)) continue;
    if (question.id.startsWith("X")) continue;
    if (!question.targets?.includes(candidateId)) continue;

    const potential = getQuestionMeasurementPotential(question, candidateId);
    if (potential <= 0) continue;

    let score = potential * 3;
    if (rivalId && question.targets?.includes(rivalId)) score += 7;

    const theme = question.theme ?? NORMAL_BRANCH_THEMES[question.id];
    if (theme && diagnosisState.recentThemes.includes(theme)) score -= 2;
    if (lastFormat && question.format === lastFormat) score -= 1;

    if (score > bestScore) {
      bestScore = score;
      bestQuestion = question;
    }
  }

  return bestQuestion;
}

function selectNormalTieBreakerQuestion(firstId, secondId) {
  const pairQuestion = findNormalPairQuestion(firstId, secondId);
  if (pairQuestion) return pairQuestion;

  let bestQuestion = null;
  let bestScore = -Infinity;

  for (const question of ALL_NORMAL_BRANCH_QUESTIONS) {
    if (diagnosisState.answeredIds.includes(question.id)) continue;
    if (question.id.startsWith("X")) continue;

    const targets = question.targets ?? [];
    const hitsFirst = targets.includes(firstId);
    const hitsSecond = targets.includes(secondId);
    if (!hitsFirst && !hitsSecond) continue;

    let score = 0;
    if (hitsFirst) score += 4 + getQuestionMeasurementPotential(question, firstId) * 2;
    if (hitsSecond) score += 4 + getQuestionMeasurementPotential(question, secondId) * 2;
    if (hitsFirst && hitsSecond) score += 8;

    if (score > bestScore) {
      bestScore = score;
      bestQuestion = question;
    }
  }

  return bestQuestion;
}


function shouldAskNormalExplorationQuestion(
  firstId
) {

  if (!firstId) {
    return false;
  }

  const recent =
    diagnosisState
      .answeredIds
      .filter(
        id =>
          NORMAL_BRANCH_QUESTION_IDS
            .has(id)
      )
      .slice(-3)
      .map(
        id =>
          getNormalBranchQuestionById(id)
      )
      .filter(Boolean);

  if (recent.length < 2) {
    return false;
  }

  // 直近3問に探索質問があれば、連発しない。
  if (
    recent.some(
      question =>
        question.id.startsWith("X")
    )
  ) {
    return false;
  }

  const targetedFirst =
    recent.filter(
      question =>
        question.targets?.includes(
          firstId
        )
    ).length;

  return targetedFirst >= 2;
}


function selectNormalExplorationQuestion(
  firstId
) {

  const targetProfile =
    NORMAL_PROFILES[firstId] ?? {};

  let bestQuestion = null;
  let bestScore = -Infinity;

  for (
    const question
    of NORMAL_EXPLORATION_QUESTIONS
  ) {

    if (
      diagnosisState
        .answeredIds
        .includes(question.id)
    ) {
      continue;
    }

    let score = 0;

    for (
      const axis
      of question.probeAxes ?? []
    ) {

      // 候補が極端な軸ほど、反対側も確認する価値が高い。
      score +=
        Math.abs(
          (targetProfile[axis] ?? 50) - 50
        ) / 10;

      // まだ測定量が少ない軸も優先。
      const evidence =
        diagnosisState
          .axisEvidence[axis] ?? 0;

      score +=
        Math.max(
          0,
          2 - evidence / 6
        );
    }

    if (
      question.theme &&
      diagnosisState
        .recentThemes
        .includes(question.theme)
    ) {
      score -= 5;
    }

    if (score > bestScore) {
      bestScore = score;
      bestQuestion = question;
    }
  }

  return bestQuestion;
}


