// =====================================================
// ノーマル分岐質問を選択
// =====================================================
function selectNextNormalBranchQuestion() {

  const profile =
    buildCurrentUserProfile();


  const ranking =
    rankNormalMonstersForBranch(
      profile
    );


  // 上位6体を参考にする
  const topMonsters =
    ranking.slice(0, 6);


  const first =
    topMonsters[0];

  const second =
    topMonsters[1];


  if (first && second) {
    const count = getNormalBranchAnswerCount();
    const gap = first.adaptiveScore - second.adaptiveScore;

    if (count >= 10 && count < 12 && gap < 2.5) {
      const tieBreaker = selectNormalTieBreakerQuestion(first.id, second.id);
      if (tieBreaker) return tieBreaker;
    }
  }


  // 接戦の上位2体に専用のペア識別質問がある場合は最優先。
  if (first && second) {

    const gap =
      first.adaptiveScore -
      second.adaptiveScore;

    const pairQuestion =
      findNormalPairQuestion(
        first.id,
        second.id
      );

    if (
      pairQuestion &&
      gap < 9
    ) {
      return pairQuestion;
    }
  }


  if (first && second) {
    const gap = first.adaptiveScore - second.adaptiveScore;
    const firstMeasurement = getNormalCandidateMeasurement(first.id);
    const secondMeasurement = getNormalCandidateMeasurement(second.id);

    if (
      gap < 10 &&
      Math.min(firstMeasurement.coverage, secondMeasurement.coverage) < 0.35
    ) {
      const underMeasured =
        firstMeasurement.coverage <= secondMeasurement.coverage
          ? first
          : second;
      const rival = underMeasured.id === first.id ? second : first;
      const question = selectNormalMeasurementQuestion(underMeasured.id, rival.id);
      if (question) return question;
    }
  }


  // 同じ候補方向へ質問が続いたら、モンスター直接点のない
  // 探索質問を1問挟んで反証可能性を残す。
  if (
    first &&
    shouldAskNormalExplorationQuestion(
      first.id
    )
  ) {

    const explorationQuestion =
      selectNormalExplorationQuestion(
        first.id
      );

    if (explorationQuestion) {
      return explorationQuestion;
    }
  }


  const recentFormats =
    diagnosisState
      .recentFormats;


  const lastFormat =
    recentFormats.at(-1);


  const secondLastFormat =
    recentFormats.at(-2);


  let bestQuestion = null;

  let bestScore = -Infinity;


  for (
    const question
    of NORMAL_BRANCH_QUESTIONS
  ) {

    // 回答済みは除外
    if (
      diagnosisState
        .answeredIds
        .includes(question.id)
    ) {

      continue;

    }


    let score = 0;


    // -----------------------------
    // 上位候補との関連度
    // -----------------------------

    topMonsters.forEach(
      (monster, index) => {

        if (
          question.targets.includes(
            monster.id
          )
        ) {

          // 1位ほど大きく加点
          score += 7 - index;

        }

      }
    );


    // -----------------------------
    // 1位と2位を直接比較できる質問を優遇
    // -----------------------------

    if (
      first &&
      second &&
      question.targets.includes(
        first.id
      ) &&
      question.targets.includes(
        second.id
      )
    ) {

      score += 6;

    }


    // -----------------------------
    // 1位のSIGNATUREをまだ十分確認していない時
    // 1位を対象に含む質問を少し優遇
    // -----------------------------

    if (
      first &&
      question.targets.includes(
        first.id
      )
    ) {

      const signatureScore =
        diagnosisState
          .signatures[
            first.signature
          ] ?? 0;


      if (signatureScore < 3) {

        score += 2;

      }

    }


    // -----------------------------
    // 同じテーマの連発を避ける
    // -----------------------------

    const theme =
      NORMAL_BRANCH_THEMES[
        question.id
      ];


    if (
      theme &&
      diagnosisState
        .recentThemes
        .includes(theme)
    ) {

      score -= 5;

    }


    // -----------------------------
    // 同じ形式の連発を避ける
    // -----------------------------

    if (
      lastFormat &&
      question.format ===
      lastFormat
    ) {

      score -= 2;

    }


    // 直近2問が同形式なら
    // 3連続をかなり避ける
    if (
      lastFormat &&
      secondLastFormat &&
      lastFormat ===
      secondLastFormat &&
      question.format ===
      lastFormat
    ) {

      score -= 6;

    }


    // EXTREMEは連発させない
    if (
      question.format ===
      "EXTREME" &&
      recentFormats.includes(
        "EXTREME"
      )
    ) {

      score -= 5;

    }


    if (
      score > bestScore
    ) {

      bestScore = score;
      bestQuestion = question;

    }

  }


  return bestQuestion;
}

// =====================================================
// 次のノーマル分岐質問へ
// =====================================================

function startNormalBranchStep() {

  diagnosisState.route =
    "NORMAL_BRANCH";

  setDiagnosisProgress(
    56,
    "モンスター候補を絞り込み中"
  );


  const nextQuestion =
    selectNextNormalBranchQuestion();


  if (!nextQuestion) {

    const questionText =
      document.getElementById(
        "questionText"
      );

    const answerButtons =
      document.getElementById(
        "answerButtons"
      );

    const answerStatus =
      document.getElementById(
        "answerStatus"
      );


    questionText.textContent =
      "分岐質問のテストが終了しました";

    answerButtons.innerHTML = "";

    answerStatus.textContent =
      "現在利用できる分岐質問をすべて確認しました。";

    return;
  }


  renderQuestion(
    nextQuestion
  );

}

// =====================================================
// 性格軸への加点
// weight で質問ごとの影響力を調整できる
// =====================================================

function applyAxisEffects(
  axisEffects = {},
  weight = 1
) {

  for (
    const [axis, value]
    of Object.entries(axisEffects)
  ) {

    if (!AXES.includes(axis)) {
      continue;
    }

    const weightedValue =
      value * weight;

    diagnosisState.axisScores[axis] +=
      weightedValue;

    diagnosisState.axisEvidence[axis] +=
      Math.abs(weightedValue);

  }

}
// =====================================================
// 特殊フラグへの加点
// =====================================================

function applyFlagEffects(flagEffects = {}) {

  for (
    const [flag, value]
    of Object.entries(flagEffects)
  ) {

    if (
      typeof diagnosisState.flags[flag]
      !== "number"
    ) {
      diagnosisState.flags[flag] = 0;
    }

    diagnosisState.flags[flag] += value;

  }

}


// =====================================================
// SIGNATUREへの加点
// =====================================================

function applySignatureEffects(
  signatureEffects = {}
) {

  for (
    const [signature, value]
    of Object.entries(signatureEffects)
  ) {

    if (
      typeof diagnosisState
        .signatures[signature]
      !== "number"
    ) {
      diagnosisState
        .signatures[signature] = 0;
    }

    diagnosisState
      .signatures[signature] += value;
  }

}


// =====================================================
// 特定モンスターへの直接適性点
// =====================================================

function applyMonsterDirectEffects(
  monsterEffects = {}
) {

  for (
    const [monsterId, value]
    of Object.entries(monsterEffects)
  ) {

    if (
      typeof diagnosisState
        .monsterDirectScores[monsterId]
      !== "number"
    ) {
      diagnosisState
        .monsterDirectScores[monsterId] = 0;
    }

    diagnosisState
      .monsterDirectScores[monsterId] += value;
  }

}


// =====================================================
// SPECIAL候補への直接適性点
// =====================================================

function applySpecialDirectEffects(
  specialEffects = {}
) {

  for (
    const [specialId, value]
    of Object.entries(specialEffects)
  ) {

    if (
      typeof diagnosisState
        .specialDirectScores[specialId]
      !== "number"
    ) {
      diagnosisState
        .specialDirectScores[specialId] = 0;
    }

    diagnosisState
      .specialDirectScores[specialId] += value;
  }

}
