// =====================================================
// ルート別の進行度目安
// =====================================================

function calculateDiagnosisProgress() {

  const coreCount =
    diagnosisState
      .answeredIds
      .filter(
        id => /^Q\d+$/.test(id)
      )
      .length;

  // N/P/Xを含む全てのノーマル分岐質問を数える。
  const branchCount =
    getNormalBranchAnswerCount();

  const specialCount =
    diagnosisState
      .answeredIds
      .filter(
        id => /^S\d+$/.test(id)
      )
      .length;

  const awakeningCount =
    diagnosisState
      .answeredIds
      .filter(
        id => id.startsWith("A_")
      )
      .length;


  switch (
    diagnosisState.route
  ) {

    case "CORE":
      return Math.min(
        55,
        3 +
        (coreCount / 24) * 52
      );

    case "NORMAL_BRANCH":
      return Math.min(
        76,
        56 +
        (branchCount / 12) * 20
      );

    case "SPECIAL_DEEP":
      return Math.min(
        92,
        77 +
        (specialCount / 10) * 15
      );

    case "AWAKENING":
      return Math.min(
        99,
        93 +
        (awakeningCount / 3) * 6
      );

    case "RESULT":
      return 100;

    default:
      return 0;
  }
}


// =====================================================
// 現在フェーズの表示名
// =====================================================

function getDiagnosisPhaseLabel() {

  switch (
    diagnosisState.route
  ) {

    case "CORE":
      return "基本性格を分析中";

    case "NORMAL_BRANCH":
      return "モンスター候補を絞り込み中";

    case "SPECIAL_DEEP":
      return "SPECIAL適性を深掘り中";

    case "AWAKENING":
      return "最終形態を判定中";

    case "RESULT":
      return "診断完了";

    default:
      return "分析中";
  }
}


// =====================================================
// 進行度を表示
// 指定値より下がらない
// =====================================================

function setDiagnosisProgress(
  target,
  phaseLabel = null
) {

  ensureDiagnosisProgressUI();

  const safeTarget =
    Math.max(
      0,
      Math.min(
        100,
        Math.round(target)
      )
    );

  const current =
    Number(
      diagnosisState
        .displayProgress ?? 0
    );

  const next =
    Math.max(
      current,
      safeTarget
    );

  diagnosisState
    .displayProgress = next;


  const phase =
    document.getElementById(
      "diagnosisProgressPhase"
    );

  const percent =
    document.getElementById(
      "diagnosisProgressPercent"
    );

  const fill =
    document.getElementById(
      "diagnosisProgressFill"
    );


  if (phase) {
    phase.textContent =
      phaseLabel ??
      getDiagnosisPhaseLabel();
  }

  if (percent) {
    percent.textContent =
      `${next}%`;
  }

  if (fill) {
    fill.style.width =
      `${next}%`;
  }
}


function updateDiagnosisProgress() {

  setDiagnosisProgress(
    calculateDiagnosisProgress(),
    getDiagnosisPhaseLabel()
  );
}


// =====================================================
// 質問切り替えの軽い演出
// =====================================================

function animateQuestionContent() {

  const targets = [
    document.getElementById(
      "questionText"
    ),
    document.getElementById(
      "answerButtons"
    )
  ];

  targets.forEach(
    element => {

      if (!element) {
        return;
      }

      element.classList.remove(
        "dq-question-enter"
      );

      // アニメーションを再実行するため再描画
      void element.offsetWidth;

      element.classList.add(
        "dq-question-enter"
      );
    }
  );
}


// =====================================================
// 質問表示
// =====================================================

function renderQuestion(question) {

  const questionText =
    document.getElementById(
      "questionText"
    );

  const answerButtons =
    document.getElementById(
      "answerButtons"
    );

  const answerStatus =
    document.getElementById(
      "answerStatus"
    );


  ensureDiagnosisProgressUI();
  updateDiagnosisProgress();


  questionText.textContent =
    question.text;

  answerButtons.innerHTML = "";

  answerStatus.textContent = "";


  question.answers.forEach(
    (answer, index) => {

      const button =
        document.createElement(
          "button"
        );

      button.className =
        "answer-button";

      button.textContent =
        `${String.fromCharCode(
          65 + index
        )}. ${answer.text}`;


      button.addEventListener(
        "click",
        () => {

          button.classList.add(
            "dq-selected-answer"
          );

          answerQuestion(
            question,
            answer
          );

        }
      );


      answerButtons.appendChild(
        button
      );

    }
  );

  animateQuestionContent();

}
// =====================================================
// 回答処理
// =====================================================

function answerQuestion(
  question,
  answer
) {

  // 同じ質問を二重回答しない
  if (
    diagnosisState
      .answeredIds
      .includes(question.id)
  ) {
    return;
  }


  // -----------------------------
  // 可変質問での回答機会を先に記録
  // -----------------------------

  recordScoringOpportunities(
    question
  );

  // -----------------------------
  // 性格軸
  // -----------------------------

  applyAxisEffects(
  answer.axes,
  question.axisWeight ?? 1
);

  // -----------------------------
  // 特殊フラグ
  // -----------------------------

  applyFlagEffects(
    answer.flags
  );

applySignatureEffects(
  answer.signatures
);

applyMonsterDirectEffects(
  answer.monsters
);

applySpecialDirectEffects(
  answer.specials
);

applyAwakeningEffects(
  answer.awakening
);

  // -----------------------------
  // 回答済みに登録
  // -----------------------------

  diagnosisState
    .answeredIds
    .push(question.id);

  diagnosisState.questionCount++;

  // STEP 10A：テスト用に質問IDと選択肢だけ記録
  // 個人情報や名前は記録しません。
  if (
    !Array.isArray(
      diagnosisState.responseHistory
    )
  ) {
    diagnosisState.responseHistory = [];
  }

  const selectedAnswerIndex =
    Array.isArray(question.answers)
      ? question.answers.indexOf(answer)
      : -1;

  diagnosisState.responseHistory.push({
    questionId: question.id,
    choice:
      selectedAnswerIndex >= 0
        ? String.fromCharCode(
            65 + selectedAnswerIndex
          )
        : "?"
  });

  updateDiagnosisProgress();
  

  recordQuestionHistory(
   question
);


  // -----------------------------
  // ボタンを一時的に無効化
  // -----------------------------

  document
    .querySelectorAll(
      ".answer-button"
    )
    .forEach(button => {

      button.disabled = true;

    });


  // -----------------------------
  // 状態表示
  // -----------------------------

  const answerStatus =
    document.getElementById(
      "answerStatus"
    );

  answerStatus.textContent =
    "回答を分析しています…";


  console.log(
    "現在の診断状態",
    diagnosisState
  );


    // -----------------------------
  // 次の質問へ
  // -----------------------------

  setTimeout(
    () => {


      // =========================
      // 共通24問
      // =========================

      if (
        diagnosisState.route ===
        "CORE"
      ) {

        const nextCoreQuestion =
          getNextCoreQuestion();


        if (
          nextCoreQuestion
        ) {

          renderQuestion(
            nextCoreQuestion
          );

        } else {

          showCoreAnalysis();

        }


        return;
      }


      // =========================
      // ノーマル分岐
      // =========================

      if (
        diagnosisState.route ===
        "NORMAL_BRANCH"
      ) {

        const progress =
          evaluateNormalBranchProgress();


        if (
          progress.shouldStop
        ) {

          showNormalBranchTestSummary();

          return;
        }


        const nextBranchQuestion =
          selectNextNormalBranchQuestion();


        if (
          nextBranchQuestion
        ) {

          renderQuestion(
            nextBranchQuestion
          );

        } else {

          diagnosisState
            .normalBranchStopReason =
            "有効な追加質問がなくなったため終了";

          showNormalBranchTestSummary();

        }

      }


      // =========================
      // SPECIAL深掘り
      // =========================

      if (
        diagnosisState.route ===
        "SPECIAL_DEEP"
      ) {

        const progress =
          evaluateSpecialDeepProgress();

        if (
          progress.shouldStop
        ) {

          showSpecialDeepSummary();
          return;
        }

        const nextSpecialQuestion =
          selectNextSpecialDeepQuestion();

        if (
          nextSpecialQuestion
        ) {

          renderQuestion(
            nextSpecialQuestion
          );

        } else {

          showSpecialDeepSummary();

        }

        return;
      }


      // =========================
      // 覚醒・変身判定
      // =========================

      if (
        diagnosisState.route ===
        "AWAKENING"
      ) {

        const progress =
          evaluateAwakeningProgress();

        if (
          progress.shouldStop
        ) {

          showAwakeningSummary();
          return;
        }

        const nextAwakeningQuestion =
          selectNextAwakeningQuestion();

        if (
          nextAwakeningQuestion
        ) {

          renderQuestion(
            nextAwakeningQuestion
          );

        } else {

          showAwakeningSummary();

        }

        return;
      }

    },

    450
  );
}

// =====================================================
// 現在の性格軸を0～100に変換
// =====================================================

function calculateNormalizedAxis(axis) {

  const score =
    diagnosisState.axisScores[axis] ?? 0;

  const evidence =
    diagnosisState.axisEvidence[axis] ?? 0;


  // まだ一度も測っていない軸は中立の50
  if (evidence <= 0) {
    return 50;
  }


  // -1 ～ +1
  const direction =
    Math.max(
      -1,
      Math.min(
        1,
        score / evidence
      )
    );


  // 質問数が少ないうちは
  // 極端な数値にならないよう50へ寄せる。
  // 係数9はランダム回答で隠し/SPECIALへ
  // 偏りすぎないようキャリブレーション済み。
  const confidence =
    1 - Math.exp(
      -evidence / 9
    );


  const value =
    50 +
    direction *
    50 *
    confidence;


  return Math.round(
    Math.max(
      0,
      Math.min(100, value)
    )
  );
}

// =====================================================
// 16軸すべてのプロフィールを作成
// =====================================================

function buildCurrentUserProfile() {

  const profile = {};

  for (const axis of AXES) {

    profile[axis] =
      calculateNormalizedAxis(axis);

  }

  return profile;
}
// =====================================================
// 共通24問終了後の暫定解析
// =====================================================

function showCoreAnalysis() {

  setDiagnosisProgress(
    55,
    "基本性格の分析が完了しました"
  );

  const profile =
    buildCurrentUserProfile();


  const ranking =
    rankNormalMonsters(profile);


  // 後で分岐診断に使うので保存
  diagnosisState.normalizedProfile =
    profile;

  diagnosisState.normalRanking =
    ranking;


  const questionText =
    document.getElementById(
      "questionText"
    );

  const answerButtons =
    document.getElementById(
      "answerButtons"
    );

  const answerStatus =
    document.getElementById(
      "answerStatus"
    );


  if (
  diagnosisState.route
  === "NORMAL_BRANCH"
) {

  questionText.textContent =
    "分岐診断の途中経過";

} else {

  questionText.textContent =
    "共通24問の解析が完了しました";

}


  answerButtons.innerHTML = "";


  const resultBox =
    document.createElement("div");

  resultBox.className =
    "analysis-output";


  const lines = [];


  lines.push("【現在の16軸】");
  lines.push("");


  AXES.forEach(axis => {

    lines.push(
      `${AXIS_LABELS[axis]}：${profile[axis]}`
    );

  });


  lines.push("");
  lines.push("【現在の上位候補】");
  lines.push("");


  ranking
    .slice(0, 5)
    .forEach(
      (monster, index) => {

        lines.push(
          `${index + 1}. ${monster.name}` +
          `  ${monster.similarity.toFixed(1)}%`
        );

      }
    );


  resultBox.textContent =
    lines.join("\n");


  answerButtons.appendChild(
    resultBox
  );
const branchButton =
  document.createElement(
    "button"
  );

branchButton.className =
  "answer-button";


if (
  diagnosisState.route
  === "NORMAL_BRANCH"
) {

  branchButton.textContent =
    "次の分岐質問へ";

} else {

  branchButton.textContent =
    "分岐診断へ進む";

}


branchButton.addEventListener(
  "click",
  startNormalBranchStep
);


answerButtons.appendChild(
  branchButton
);


  answerStatus.textContent =
    "※これは途中経過です。最終結果ではありません。";

}



// =====================================================
// 診断開始
// =====================================================

function startDiagnosis() {

  diagnosisState =
    createInitialState();


  document
    .getElementById(
      "startScreen"
    )
    .classList
    .add("hidden");


  document
    .getElementById(
      "questionScreen"
    )
    .classList
    .remove("hidden");


  ensureDiagnosisProgressUI();

  setDiagnosisProgress(
    3,
    "基本性格を分析中"
  );


  renderQuestion(
    CORE_QUESTIONS[0]
  );


}
// =====================================================
// 次の未回答共通質問を探す
// =====================================================

function getNextCoreQuestion() {

  return CORE_QUESTIONS.find(
    question =>
      !diagnosisState
        .answeredIds
        .includes(question.id)
  );

}


